<html>
<head>
'+css+'
<meta charset="UTF-8">
</head>
<body>
  <canvas id="searchlights" ></canvas>

<script>
var canvasWidth = parseInt(getComputedStyle(document.getElementById("searchlights")).width);
var canvasHeight = parseInt(getComputedStyle(document.getElementById("searchlights")).height);

var particles = [];

var particleCount = parseInt(canvasWidth/400*25);

var maxVelocity = 1;

var targetFPS = 60;

var imageObj = new Image();

imageObj.onload = function() {
    particles.forEach(function(particle) {
            particle.setImage(imageObj);
    });
};

imageObj.src = `data:image/svg+xml;utf8,
<svg
 xmlns:svg="http://www.w3.org/2000/svg"
 xmlns="http://www.w3.org/2000/svg"
 xmlns:xlink="http://www.w3.org/1999/xlink"
>
<defs
 id="defs2">
<linearGradient
 id="linearGradient847">
	<stop
	 id="stop843"
	 offset="0"
	 style="stop-color:#4d4d4d;stop-opacity:.1;" />
	<stop
	 id="stop845"
	 offset="1"
	 style="stop-color:#4d4d4d;stop-opacity:0.6;" />
</linearGradient>
<radialGradient
 gradientUnits="userSpaceOnUse"
 r="54.4"
 fy="50"
 fx="50"
 cy="50"
 cx="50"
 id="radialGradient851"
 xlink:href="#linearGradient847" />
</defs>

<g
 id="layer1">
<circle 
 id="path833"
 cx="50"
 cy="50"
 r="50"
 style="fill:url(#radialGradient851);fill-opacity:1;stroke:none;stroke-width:0;stroke-linecap:butt;stroke-linejoin:miter;stroke-opacity:1;" />
</g>
</svg>
`;

function Particle(context) {

    this.x = 0;
    this.y = 0;

    this.xVelocity = 0;
    this.yVelocity = 0;

    this.radius = 25;

    this.context = context;

    this.draw = function() {
        if(this.image){
            this.context.drawImage(this.image, this.x-128, this.y-128);         
            return;
        }
        this.context.beginPath();
        this.context.arc(this.x, this.y, this.radius, 0, 2 * Math.PI, false);
        this.context.fillStyle = "rgba(225, 211, 255, 0.50)";
        this.context.fill();
        this.context.closePath();
    };

    this.update = function() {
        this.x += this.xVelocity;
        this.y += this.yVelocity;

        if (this.x >= canvasWidth) {
            this.xVelocity = -this.xVelocity;
            this.x = canvasWidth;
        }
        else if (this.x <= 0) {
            this.xVelocity = -this.xVelocity;
            this.x = 0;
        }

        if (this.y >= canvasHeight) {
            this.yVelocity = -this.yVelocity;
            this.y = canvasHeight;
        }

        else if (this.y <= 0) {
            this.yVelocity = -this.yVelocity;
            this.y = 0;
        }
    };

    this.setPosition = function(x, y) {
        this.x = x;
        this.y = y;
    };
    this.setVelocity = function(x, y) {
        this.xVelocity = x;
        this.yVelocity = y;
    };

    this.setImage = function(image){
        this.image = image;
    }
}


function generateRandom(min, max){
    return Math.random() * (max - min) + min;
}

var context;

function init() {
    var canvas = document.getElementById("searchlights");
    if (canvas.getContext) {
        context = canvas.getContext("2d");
        for(var i=0; i < particleCount; ++i){
            var particle = new Particle(context);
            particle.setPosition(generateRandom(0, canvasWidth), generateRandom(0, canvasHeight));
            particle.setVelocity(generateRandom(-maxVelocity, maxVelocity), generateRandom(-maxVelocity, maxVelocity));
            particles.push(particle);            
        }
    }
    else {
        alert("Please use a modern browser");
    }
}

function draw() {
    context.fillStyle = "rgba(0, 0, 0, 0.1)";
    context.fillRect(0, 0, 400, 400);
    particles.forEach(function(particle) {
        particle.draw();
    });
}

function update() {
    particles.forEach(function(particle) {
        particle.update();
    });
}

init();

if (context) {
    setInterval(function() {
        update();
        draw();
    }, 1000 / targetFPS);
}
</script>
</body>
</html>
' ]
}]

