<html>
<head>
<meta charset="UTF-8">
<script src="https://cdnjs.cloudflare.com/ajax/libs/p5.js/0.5.16/p5.min.js"></script>

<style>
'+css+'
</style>
</head>
<body onload="setup()">
<canvas id="bgCanvas"></canvas>
<script type="text/javascript">
var sky;
var stars = [];

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
}

function setup() {
  createCanvas(windowWidth, windowHeight);
  sky = new StarSky();
  background(8, 15, 23, 20);
}

function draw() {
  fill(8, 15, 23, 20);
  noStroke();
  rectMode(CENTER);
  rect(width/2, height/2, width, height);

  sky.run();
}

var StarSky = function() {

  this.starsnumber = 10;
  this.stars = [];
  this.wind;

  for (var i = 0; i < this.starsnumber; i++) {
    var s = new Star();
    this.stars.push(s);
  }

  this.run = function() {
    this.wind = noise(frameCount/1000)*5;
    for (var i = 0; i < this.stars.length; i++) {
      this.stars[i].anim(this.wind);
      this.stars[i].display();

      if (!this.stars[i].alive) this.stars.splice(i, 1);
    }

    if (stars.length < this.starsnumber) {
      for (var i = 0; i < 1; i++) {
        var s = new Star();
        this.stars.push(s);
      }
    }
  }
}

var Star = function() {

  this.position = createVector(random(-width/2, width), random(-height, height));
  this.acceleration = createVector(0, 0, 0);
  this.velocity = createVector(0, 0, 0);
  this.brightness;
  this.weight = random(5, 9);
  this.anim = random(TWO_PI);
  this.size = cos(this.anim)*2;
  this.alive = true;

  this.anim = function(wind) {
    this.acceleration.mult(0);
    this.acceleration.y += this.weight;
    this.acceleration.x += wind;
    this.acceleration.limit(1);
    this.velocity.add(this.acceleration);
    this.velocity.limit(1);
    this.position.add(this.velocity);
    if (this.position.y > height) this.alive = false;
  }

  this.display = function() {
    stroke(255);
    strokeWeight(this.size+0.2);
    point(this.position.x, this.position.y);
  }
}

</script>
</body>
</html>
']
