[r: strformat('
<html>
<head>
<meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<style>%{css}</style>
</head>
<body>

<script>
"use strict"
console.clear();
const dft={radius:3.2,colours:["#d5bb6d","#c2b280","#afa892","#cbb676"],mass:0.001,charge:1,gradient:false}
function Particle(radius,colours,mass,charge,gradient){if(typeof(radius)==="undefined")radius=prt.radius;if(typeof(colours)==="undefined")colours=prt.colours;if(typeof(mass)==="undefined")mass=prt.mass;if(typeof(charge)==="undefined")charge=prt.charge;if(typeof(gradient)==="undefined")gradient=prt.gradient;this.radius=radius;this.colours=colours;this.lastcolor=0;this.mass=mass;this.charge=charge;this.gradient=gradient;this.x=0;this.y=0;this.vx=(Math.random()-0.5)*8;this.vy=(Math.random()-0.5)*5;this.life=0;this.lifetime=1;this.alpha=this.calcAlpha();this.vUnit=this.velo2D.unit();this.startframe;this.speed;this.type;}
Particle.prototype.constructor=Particle;Particle.prototype={get pos2D(){return new Vector2D(this.x,this.y);},set pos2D(pos){this.x=pos.x;this.y=pos.y;},get velo2D(){return new Vector2D(this.vx,this.vy);},set velo2D(velo){this.vx=velo.x;this.vy=velo.y;},age:function(dt){if(typeof dt==="undefined")dt=1;this.life+=dt;return this.life>this.lifetime;},calcAlpha:function(){var decValue=parseInt((1-(this.life/this.lifetime))*(this.life/this.lifetime)*4*255);var hexString=decValue.toString(16);if((hexString.length%2)>0){hexString="0"+hexString}
return hexString},draw:function(context){if(this.gradient){var grad=context.createRadialGradient(this.x,this.y,0,this.x,this.y,this.radius);grad.addColorStop(0,this.colours[0]);grad.addColorStop(1,this.colours[this.colours.length]);context.fillStyle=grad;}else{this.lastcolor=this.lastcolor==this.colours.length?0:this.lastcolor++;context.fillStyle=this.colours[this.lastcolor];}
context.beginPath();context.arc(this.x,this.y,this.radius,0,2*Math.PI,true);context.closePath();context.fill();},drawLine:function(context){var lineEnd=this.pos2D.add(this.velo2D.multiply(0.051));if(this.gradient){var grad=context.createLinearGradient(this.x,this.y,lineEnd.x,lineEnd.y);grad.addColorStop(0.0,this.colours[0]+"00");grad.addColorStop(0.3,this.colours[0]);grad.addColorStop(0.6,this.colours[this.colours.length-1]+"a1");grad.addColorStop(1.0,this.colours[this.colours.length-1]+"00");context.strokeStyle=grad;}else{this.lastcolor=this.lastcolor==this.colours.length?0:this.lastcolor++;context.strokeStyle=this.colours[this.lastcolor];}
var lineEnd=this.pos2D.add(this.velo2D.multiply(0.03));context.lineWidth=2;context.beginPath();context.moveTo(this.x,this.y);context.lineTo(lineEnd.x,lineEnd.y);context.closePath();context.stroke();},wrap:function(canvas){if(this.x<0){this.x=canvas.width-Math.floor(Math.random()*12)}
if(this.x>canvas.width){this.x=Math.floor(Math.random()*12)}
if(this.y<0){this.y=canvas.height-Math.floor(Math.random()*12)}
if(this.y>canvas.height){this.y=Math.floor(Math.random()*12)}}};

function Vector2D(x,y){if(typeof x==="undefined")x=0;if(typeof y==="undefined")y=0;this.x=parseFloat(x);this.y=parseFloat(y);}
Vector2D.prototype={lengthSquared:function(){return this.x*this.x+this.y*this.y;},length:function(){return Math.sqrt(this.lengthSquared());},angle:function(){return Math.atan2(this.y,this.x);},clone:function(){return new Vector2D(this.x,this.y);},negate:function(){return new Vector2D(this.x==0?0:-this.x,this.y==0?0:-this.y)},unit:function(){var length=this.length();if(length>0){return new Vector2D(this.x/length,this.y/length);}else{return new Vector2D(0,0);}},normalize:function(){var length=this.length();if(length>0){this.x/=length;this.y/=length;}
return this.length();},add:function(vec){return new Vector2D(this.x+vec.x,this.y+vec.y);},incrementBy:function(vec){this.x+=vec.x;this.y+=vec.y;},subtract:function(vec){return new Vector2D(this.x-vec.x,this.y-vec.y);},decrementBy:function(vec){this.x-=vec.x;this.y-=vec.y;},multiply:function(k){return new Vector2D(k*this.x,k*this.y);},inverse:function(){var x,y;if(this.x==0){x=0}else{x=1/this.x};if(this.y==0){y=0}else{y=1/this.y};return new Vector2D(x,y);},addScaled:function(vec,k){return new Vector2D(this.x+k*vec.x,this.y+k*vec.y);},scaleBy:function(k){this.x*=k;this.y*=k;},dotProduct:function(vec){return this.x*vec.x+this.y*vec.y;},crossProduct:function(vec){return this.x*vec.y-this.y*vec.x;},projection:function(vec){var length=this.length();var lengthVec=vec.length();var proj;if((length==0)||(lengthVec==0)){proj=0;}else{proj=(this.x*vec.x+this.y*vec.y)/lengthVec;}
return proj;},project:function(vec){return vec.para(this.projection(vec));},para:function(u,positive){if(typeof(positive)==="undefined")positive=true;var length=this.length();var vec=new Vector2D(this.x,this.y);if(positive){vec.scaleBy(u/length);}else{vec.scaleBy(-u/length);}
return vec;},perp:function(u,anticlockwise){if(typeof(anticlockwise)==="undefined")anticlockwise=true;var length=this.length();var vec=new Vector2D(this.y,-this.x);if(length>0){if(anticlockwise){vec.scaleBy(u/length);}else{vec.scaleBy(-u/length);}}else{vec=new Vector2D(0,0);}
return vec;},rotate:function(angle){return new Vector2D(this.x*Math.cos(angle)-this.y*Math.sin(angle),this.x*Math.sin(angle)+this.y*Math.cos(angle));}};Vector2D.distance=function(vec1,vec2){return(vec1.subtract(vec2)).length();};Vector2D.angleBetween=function(vec1,vec2){return Math.acos(vec1.dotProduct(vec2)/(vec1.length()*vec2.length()));};Vector2D.scale=function(vec,sca){vec.x*=sca;vec.y*=sca;};Vector2D.vector2D=function(mag,angle,clockwise){if(typeof(clockwise)==="undefined")clockwise=true;var vec=new Vector2D(0,0);vec.x=mag*Math.cos(angle);vec.y=mag*Math.sin(angle);if(!clockwise){vec.y*=-1;};return vec;};

const
	prt = {radius: .62,
		colours: [["#80ff00","#80ff00"],
				 ["#ffd500","#ffd500"],
				 ["#ff8888","#ff8888"],
				 ["#fafafa","#fafafa"]],
		gradient: true,
		life:1000 
    },
	fps = 26,
	bulletSpeed = 800;

var	winWidth = window.innerWidth,
	winHeight= window.innerHeight,
	winCenW  = winWidth/2,
	winCenH  = winHeight/2,
	winCenter= new Vector2D(winCenW, winCenH),
	winLength= 2*winWidth+2*winHeight,
	canvas,
	context,
	animId,
	t0 = 0,dt,
	frame = 0,
	sporadic  = new Array(),
	chainfire = new Array(),
	explosion,
	maxParticles = Math.floor(winWidth*3/winHeight),
	timescale = 2000;

function startPoint(num) {
	num = parseInt(num);
	var vec = new Vector2D();
	if(num < winWidth) { vec.x=num; vec.y=0;
	} else if(num < winWidth+winHeight  ) { vec.x=winWidth; vec.y=num-winWidth; 		    
	} else if(num < 2*winWidth+winHeight) { vec.x=num-winWidth-winHeight; vec.y=winHeight;
	} else { vec.x=0; vec.y=num-2*winWidth-winHeight;		}
	return vec;
}
function startDirection(startPoint) {
	//return startPoint.subtract(winCenter).unit();
	return winCenter.subtract(startPoint).unit().rotate(Math.random()/5);
}
function createCanvas() {
	canvas  = document.createElement("canvas");
	canvas.width = winWidth;
	canvas.height = winHeight;
	document.body.appendChild(canvas);
	canvas.classList.add("firefight");
	return canvas;
}
function init() {
	canvas = createCanvas();
	context = canvas.getContext("2d"); 
	for (var i=0; i< maxParticles; i++){ spawn() }
	for (var i=0; i< maxParticles; i++){ spawn(3+Math.floor(Math.random()*6)) }
	explosion = new Explosion();
	explosion.setup();
	animFrame();
}
function spawn(num) {
	if(typeof num === "undefined") num =1;
	var particle, partArr = new Array();
	for(var i=0; i<num; i++){
		particle=new Particle();
		particle.lifetime  = prt.life;
		particle.colours   = prt.colours[Math.floor(Math.random()*prt.colours.length)];
		particle.lastcolor = Math.floor(Math.random()*particle.colours.length);
		particle.speed	   = bulletSpeed;
		if(num ==1) {
			sporadic.push(particle);
			respawn(particle);
		} else {
			partArr.push(particle);
		}
	}
	if(num > 1) {
		respawn(partArr);
		chainfire.push(partArr);
		}
}
function respawn(obj) {
	var particles;
	if(typeof obj.length === "undefined") { particles=[obj]; } else { particles=obj; };
	var num = particles.length;
	if(num > 1) {
		var swingArc = Math.random()*Math.random();
	}
	var particle;

	for(var i=0; i < num; i++)	{
		particle = particles[i];
		if(i == 0) {
			particle.life      = Math.floor(Math.random()+Math.random()/0.8*prt.life);
			particle.pos2D     = startPoint(Math.random()*winLength);
			particle.lastpos   = particle.pos2D;
			particle.velo2D    = startDirection(particle.pos2D);
			particle.velo2D    = particle.velo2D.multiply(bulletSpeed);
			particle.colours   = prt.colours[Math.floor(Math.random()*prt.colours.length)];
			particle.startframe= frame + Math.floor(Math.random()*maxParticles*timescale);
		} else {
			particle.life      = particles[0].life;
			particle.pos2D     = particles[0].pos2D;
			particle.lastpos   = particles[0].pos2D;
			particle.velo2D    = particles[0].velo2D.rotate(-swingArc/2+swingArc*i);
			particle.startframe= particles[0].startframe+i*2*fps;
			particle.colours   = particles[0].colours;
		}
	}
}
function animFrame(){
    setInterval(function() {
          animId = requestAnimationFrame(animFrame,canvas);
          onTimer();
    }, 1000/fps);
}

function onTimer(){
	var t1 = new Date().getTime(); 
	dt = 0.001*(t1-t0); 
	t0 = t1;
	if (dt>0.2) {dt=0;};

	if(dt>0){ 
		frame++;
		move()
		}
}
function move(){
	context.clearRect(0, 0, winWidth, winHeight);

	var particles=sporadic.concat(chainfire);
	for (var i=0; i < sporadic.length; i++){
		var obj = particles[i];
		if(obj.startframe <= frame) {
			moveParticle(obj)
			obj.drawLine(context);
			if(obj.age() || obj.x < 0 || obj.x > canvas.width || obj.y < 0 || obj.y > canvas.height) respawn(obj);
		}
	}	
	for (var i=0; i < chainfire.length; i++){ var tmpPart = chainfire[i];
	for (var ii=0; ii < tmpPart.length; ii++){
		var obj = tmpPart[ii];
		if(obj.startframe <= frame) {
			moveParticle(obj)
			obj.drawLine(context);
			if(ii < tmpPart.length-1 && obj.age() || obj.x < 0 || obj.x > canvas.width || obj.y < 0 || obj.y > canvas.height) 
			{respawn(chainfire[i]);}
		}	
	}}

	if(explosion.startframe <= frame) explosion.draw(context, dt)
}
function moveParticle(obj){
	var damping = 1-0.05;
	obj.velo2D = obj.velo2D.subtract(obj.velo2D.multiply(damping*dt));
	obj.lastpos = obj.pos2D;
	obj.pos2D = obj.pos2D.addScaled(obj.velo2D, dt);
}
function Explosion() {
	this.life;
	this.lifespan;
	this.radius;
	this.size;
	this.startframe;
	this.x;
	this.y;
	}
Explosion.prototype.constructor = Explosion;
Explosion.prototype = {
	setup: function(){
		this.life = 0;
		this.lifespan = 3; //0.2+Math.random()*0.8;
		this.radius = 1+Math.random()*Math.random()*6;
		this.size = 80;
		this.startframe = frame+Math.floor(Math.random()*2300);
		this.x = Math.floor(winWidth*Math.random());
		this.y = Math.floor(winHeight*Math.random());
	},
	draw: function(ctx, dt) {
		var factor = 0.1-this.life;
		this.radius += this.radius*factor;
		var grd = ctx.createRadialGradient(this.x, this.y, 0, this.x, this.y, this.radius);
		grd.addColorStop(0.000, "#ffffff00");//grd.addColorStop(0.000, "#ffffff00");
		grd.addColorStop(0.375, "#ffffff02");//grd.addColorStop(0.375, "#ffffff06");
		grd.addColorStop(0.707, "#ffffff04");//grd.addColorStop(0.707, "#ffffff0B");
		grd.addColorStop(0.927, "#ffffff0B");//grd.addColorStop(0.927, "#ffffff11");
		grd.addColorStop(1.000, "#ffffff11");//grd.addColorStop(1.000, "#ffffff19");
		ctx.fillStyle = grd;
		ctx.beginPath();
		ctx.arc(this.x, this.y, this.radius, 0, 2*Math.PI, true);	
		ctx.fill();
		this.life+=dt;
		if(this.life > this.lifespan || this.radius < 1) this.setup();
	}
};
window.onresize = function() {
	canvas.width = winWidth;
	canvas.height = winHeight;
	}
window.onload = init;
</script>
</script>
</body>
</html>
')]
}]

