const defaults={charge:0,colours:["orange","red"],gradient:false,mass:1,radius:40,scale:0.2,spinRate:0.001,vortexLifetime:-1};function Vortex(radius,spinRate,age){if(typeof radius==="undefined")radius=defaults.radius;if(typeof spinRate==="undefined")spinRate=defaults.spinRate;if(typeof age==="undefined")age=Math.floor(Math.random()*this.lifeTime);this.charge=defaults.charge;this.colours=defaults.colours;this.gradient=defaults.gradient;this.lastcolor=0;this.life=age;this.lifetime=defaults.vortexLifetime;this.mass=defaults.mass;this.mass_=defaults.mass;this.radius=radius;this.radius_=radius;this.scale=defaults.scale;this.spinRate=spinRate;this.x=0;this.y=0;this.vx=0;this.vy=0;};Vortex.prototype.constructor=Vortex;Vortex.prototype={get pos2D(){return new Vector2D(this.x,this.y);},set pos2D(pos){this.x=pos.x;this.y=pos.y;},get velo2D(){return new Vector2D(this.vx,this.vy);},set velo2D(velo){this.vx=velo.x;this.vy=velo.y;},draw:function(context){if(this.gradient){var grad=context.createRadialGradient(this.x,this.y,0,this.x,this.y,this.radius);grad.addColorStop(0,this.colours[0]);grad.addColorStop(1,this.colours[this.colours.length]);context.fillStyle=grad;}else{this.lastcolor=this.lastcolor==this.colours.length?0:this.lastcolor++;context.fillStyle=this.colours[this.lastcolor];};context.beginPath();context.arc(this.x,this.y,this.radius,0,2*Math.PI,true);context.closePath();context.fill();},respawn:function(radius,spinRate,obj){if(typeof radius==="undefined")radius=defaults.radius;if(typeof spinRate==="undefined")spinRate=defaults.spinRate;if(typeof obj==="undefined")obj={};if(obj["x"]){this.x=obj["x"]}else{this.x=0};if(obj["y"]){this.y=obj["y"]}else{this.y=0};if(obj["vx"]){this.vx=obj["vx"]}else{this.vx=0};if(obj["vy"]){this.vy=obj["vy"]}else{this.vy=0};if(obj["life"]){this.life=obj["life"]}else{this.life=0};if(obj["lifetime"]==="undefined"){this.lifetime=defaults.vortexLifetime}else{this.lifeTime=obj["lifetime"]};this.radius=radius;this.spinRate=spinRate;if(obj["scale"]){this.scale=obj["scale"]}else{this.scale=defaults.scale};console.log(this.radius);},update:function(dt){if(typeof dt==="undefined")dt=1;this.life-=1;var damping=1-0.015*dt;this.vx*=damping;this.vy*=damping;this.x+=this.vx*dt;this.y+=this.vy*dt;if(Math.ceil(this.life)==0)this.respawn();if(this.x<0)this.x=window.innerWidth;if(this.x>winWidth)this.x=0;if(this.y<0)this.y=window.innerHeight;if(this.y>winHeight)this.y=0;var lifeFactor=Math.ceil(this.life)/this.lifetime;this.radius=this.radius_-this.radius_*(1-lifeFactor)*lifeFactor*4;this.mass=8*this.mass_-this.mass_*(1-lifeFactor)*lifeFactor*4;}};

