function Particle(radius,colours,mass,charge,gradient){if(typeof(radius)==="undefined")radius=prt.radius;if(typeof(colours)==="undefined")colours=prt.colours;if(typeof(mass)==="undefined")mass=prt.mass;if(typeof(charge)==="undefined")charge=prt.charge;if(typeof(gradient)==="undefined")gradient=prt.gradient;this.radius=radius;this.colours=colours;this.lastcolor=0;this.mass=mass;this.charge=charge;this.gradient=gradient;this.x=0;this.y=0;this.vx=(Math.random()-0.5)*8;this.vy=(Math.random()-0.5)*5;this.life=0;this.lifetime=1;this.alpha=this.calcAlpha();this.vUnit=this.velo2D.unit();this.startframe;this.speed;this.type;}
Particle.prototype.constructor=Particle;Particle.prototype={get pos2D(){return new Vector2D(this.x,this.y);},set pos2D(pos){this.x=pos.x;this.y=pos.y;},get velo2D(){return new Vector2D(this.vx,this.vy);},set velo2D(velo){this.vx=velo.x;this.vy=velo.y;},age:function(dt){if(typeof dt==="undefined")dt=1;this.life+=dt;return this.life>this.lifetime;},calcAlpha:function(){var decValue=parseInt((1-(this.life/this.lifetime))*(this.life/this.lifetime)*4*255);var hexString=decValue.toString(16);if((hexString.length%2)>0){hexString="0"+hexString}
return hexString},draw:function(context){if(this.gradient){var grad=context.createRadialGradient(this.x,this.y,0,this.x,this.y,this.radius);grad.addColorStop(0,this.colours[0]);grad.addColorStop(1,this.colours[this.colours.length]);context.fillStyle=grad;}else{this.lastcolor=this.lastcolor==this.colours.length?0:this.lastcolor++;context.fillStyle=this.colours[this.lastcolor];}
context.beginPath();context.arc(this.x,this.y,this.radius,0,2*Math.PI,true);context.closePath();context.fill();},drawLine:function(context){var lineEnd=this.pos2D.add(this.velo2D.multiply(0.051));if(this.gradient){var grad=context.createLinearGradient(this.x,this.y,lineEnd.x,lineEnd.y);grad.addColorStop(0.0,this.colours[0]+"00");grad.addColorStop(0.3,this.colours[0]);grad.addColorStop(0.6,this.colours[this.colours.length-1]+"a1");grad.addColorStop(1.0,this.colours[this.colours.length-1]+"00");context.strokeStyle=grad;}else{this.lastcolor=this.lastcolor==this.colours.length?0:this.lastcolor++;context.strokeStyle=this.colours[this.lastcolor];}
var lineEnd=this.pos2D.add(this.velo2D.multiply(0.03));context.lineWidth=2;context.beginPath();context.moveTo(this.x,this.y);context.lineTo(lineEnd.x,lineEnd.y);context.closePath();context.stroke();},
