table {width: 90%;}

.searchBar {
	background-position: 10px 12px;
	background-repeat: no-repeat;
	width: 90%;
	font-size: 16px;
	padding: 12px 20px 12px 40px;
	border: 1px solid #ddd;
	margin-bottom: 12px;
}

.circle {
	height:4px;
	width: 4px;
	border-radius: 50%;
	border: 2px solid #4a6898;
	cursor: grab;
}

table.editCustomSpell{
	border-spacing: 0;
	border-collapse: collapse;
}

.dropdown {
  position: relative;
  display: inline-block;
}

.dropbtn {
  color: #822000;
  padding: 2px;
  font-size: 1em;
  border: none;
  cursor: grab;
  background-color: #FDF1DC;
  font-family: Georgia, serif;
}

.dropbtn:hover, .dropbtn:focus {
  background-color: #FAEBD7;
}


/* Dropdown Content (Hidden by Default) */
.dropdown-content {
  display: none;
  position: absolute;
  background-color: #f1f1f1;
  min-width: 160px;
  box-shadow: 0px 8px 16px 0px rgba(0,0,0,0.2);
  z-index: 1;
}

/* Show the dropdown menu (use JS to add this class to the .dropdown-content container when the user clicks on the dropdown button) */
.show {display:block;}


/* Choices inside the dropdown */
.dropdown-content span {
  color: black;
  padding: 12px 16px;
  text-decoration: none;
  display: block;
}


.circle.prepared {
	background-color: #4a6898;
}

.circle.always{
	background-color: green;
	border: 2px solid green;
	cursor: default;
}


.learn {
    background-color:#4a6898;
    color: #fff;
    font-size: 0.8em;
}

.forget {
    background-color:#822000;
    color: #fff;
    font-size: 0.7em;
    padding-top: 4px;
    padding-bottom: 3px;
}


.spellName {
	float: left;
	color: #822000;
	font-size: 1.4em;
}

.source {
	position: absolute;
	right: 10px;
	color: #4a6898;
	font-size: 1.4em;
}

body {
    background-color: #FDF1DC;
	font-family: Georgia, serif;
	line-height: 2.5;
}


.schoolLevel {
	font-style: italic;
}

.share {
	text-align: right;
}

.macro {
	text-align: right;
	font-size: 0.7em;
}

.page {
	font-size: 0.6em;
	color: #333333;
}

.label {font-weight: bold;	}

p { line-height: 1.5; }

td {line-height: 1.5;}

.toggle {
	font-size: 1.2em;
	font-weight: bold;
	cursor: grab;
	text-align: center;
	vertical-align: center;
}

.divider {
	border-top: 2px solid black;
}

.middivider {
	border-top: 0px solid black;
}

.caption {
	color: #777777;
	font-size: 1.1em;
	font-weight: bold;
}

.header {
	color: #822000;
	font-weight: bold;
}

.smalltable{
	width: 0px;
	margin: 0 auto;
}

a{
	color: #822000;
}


.pseudolink {
  background: none!important;
  border: none;
  padding: 0!important;
  color: #822000;
  text-decoration: underline;
  cursor: pointer;
  font-family: Georgia, serif;
  font-size: 1em;
}


.spellHeader{
	 -webkit-user-select: none;	
}

.unselectable {
	 -webkit-user-select: none;
}

/* Style the buttons */
.selector {
  border: none;
  outline: none;
  padding: 8px 12px;
  background-color: #f1f1f1;
  cursor: pointer;
  width: 70px;
}

.selector:hover {
  background-color: #ddd;
}

.selector.active {
  background-color: #666;
  color: white;
}

