<script> 
	var vSpells  = [r: getLibProperty('Spells', vLib)];
	var vCustomSpells = [r: getLibProperty('CustomSpells', vLib)];
	var vNorm = (t) => String(t).toLowerCase().replace(/\u2019/g, "'").replace(/`/g, "'").trim();
	var vQuery = vNorm("[r: vSpell]");
	var vEngName = (el) => vNorm(el.name.lastIndexOf('(') >= 0 ? el.name.substring(el.name.lastIndexOf('(') + 1, el.name.lastIndexOf(')')) : el.name);
	var vRusName = (el) => vNorm(el.name.lastIndexOf('(') >= 0 ? el.name.substring(0, el.name.lastIndexOf('(')) : el.name);
	var vFind = (list) => list.find(el => vNorm(el.name) === vQuery) || list.find(el => vEngName(el) === vQuery) || list.find(el => vRusName(el) === vQuery);
	var vSpell = vFind(vSpells);
	vSpell = vSpell || vFind(vCustomSpells);

	var vIsGM = ([r:isGM()] == 1);

	var vKnown  = [r: vKnown];
	var vCasterId = '[r: vCurrentId]';
	var vCasterName = '[r: vName]';
	var vIsToken = vCasterId !== '';
	var vDefaultStat = '[r: vDefaultStat]';
	var vDefaultDC   = '[r: vDefaultDC]';

	var linkCondition = "[r: macroLinkText('condition@Lib:SpellLibrary', 'all', '', vCurrentId)]";
	var linkDamage = "[r: macroLinkText('damage@Lib:SpellLibrary', 'all', '', vCurrentId)]";	
	var linkHit = "[r: macroLinkText('hit@Lib:SpellLibrary', 'all', '', vCurrentId)]";
	var linkCreature = "[r: macroLinkText('creature@Lib:SpellLibrary', 'all', '', vCurrentId)]";
	var linkRoll = "[r: macroLinkText('roll@Lib:SpellLibrary', 'all', '', vCurrentId)]";
	var linkChance = "[r: macroLinkText('chance@Lib:SpellLibrary', 'all', '', vCurrentId)]";
	var linkAttack = "[r: macroLinkText('attack@Lib:SpellLibrary', 'all', '', vCurrentId)]";
	var linkSavingThrow = "[r: macroLinkText('savingThrow@Lib:SpellLibrary', 'all', '', vCurrentId)]";
	var linkCheck = "[r: macroLinkText('check@Lib:SpellLibrary', 'all', '', vCurrentId)]";
	var linkSkill = "[r: macroLinkText('skill@Lib:SpellLibrary', 'all', '', vCurrentId)]";
	var linkSpell = "[r: macroLinkText('Show a Spell@Lib:SpellLibrary', 'none', vTitle, vCurrentId)]";
	var linkConcentration = "[r: macroLinkText('concentration@Lib:SpellLibrary', 'all', '', vCurrentId)]";
	var linkShare = "[r: macroLinkText('share@Lib:SpellLibrary', 'all', '', vCurrentId)]";
	var linkMacro = "[r: macroLinkText('createMacro@Lib:SpellLibrary', 'self', '', vCurrentId)]";

	const QuoteSymbol = unescape("%27");
</script>

