[H: flag = input("vIndex|" + vChoices + "|Select Spell to Edit|LIST|DELIMITER=JSON",
"dummy|dummy|        OR|LABEL|TEXT=FALSE",
"vDelete|0|Delete this spell ?|CHECK")]

[H: abort(flag)]

[r, if(vDelete == 1), CODE:{
	[h: vCustomSpells = json.remove(vCustomSpells, vIndex)]
	[h: setLibProperty("CustomSpells", vCustomSpells)]
};{
	[macro("Add Custom Spell@this"):vIndex]
}]

