		[h: createMacro(vSpellName, vCommand, vProp, 'json')]
		Added [r:vSpellName] macro.
};{
	    [r:vSpellName] macro already exists.
}]

[h: tParse = macro.args]

[h, if(length(tParse)<=0),CODE:{
[h: text='<html><br>Syntax for use - macro("Spell Lookup@Lib:SpellLibrary"):Td<br>'+
'&nbsp;&nbsp;Where T is for type: S or L<br>'+
'&nbsp;&nbsp;Where d is for data:<br>'+
'&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;if S, data is a spellname<br>'+
'&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;if L data is a level and class syntax: Lc<br>'+
'&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;L is for level 0-9<br>'+
'&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;c is for class acronym (wiz, dru, etc)</html>']
	[assert(0, text)]
}]

[h: tLookupType = substring(tParse,0,1)]

[h, if(tLookupType=="L"),CODE:{	
	[h: tLevel = substring(tParse,1,2)]
	[h: tClass = substring(tParse,2)]
	[h: tData = ""]
};{
	[h: tLevel = ""]
	[h: tClass = ""]
	[h: tData = substring(tParse,1)]
}]

[h: allSpells = getLibProperty("Spells","Lib:SpellLibrary")]
[h: allCustomSpells = getLibProperty("CustomSpells","Lib:SpellLibrary")]

[h: allSpells = json.merge(allSpells,allCustomSpells)]

[h: sLoop = 0][h: Done = 0]
[h, while(sLoop<=1000 && Done==0 && length(allSpells)>=10),CODE:{
	[h: oneSpell = json.get(allSpells,0)]
	[h: sName = json.get(oneSpell,"name")]
	[h: sLevel = json.get(oneSpell,"level")]
	[h: sClass = json.path.read(oneSpell,".classes..name")]
	[h, if(tLookupType=="S" && lower(sName)==tData),CODE:{
		[h: sLevel = if(sLevel=="0","c",sLevel)]
		[h: tData = sName+","+sLevel]
		[h: Done = 1]
	}]
	[h, if(tLookupType=="L" && tLevel==sLevel && indexOf(sClass,tClass)>=0),CODE:{
		[h: tData = listAppend(tData,sName)]
	}]
	[h: allSpells = json.remove(allSpells,0)]
	[h: sLoop = sLoop + 1]
}]
[h, if(tLookupType=="S" && Done==0),CODE:{
	[h, if(indexOf(tData,"'")>=0),CODE:{
		[h: tData = "S"+replace(tData,"'","`")]
		[macro("Spell Lookup@Lib:SpellLibrary"):tData]
	};{
		[h: setProperty("Testing",tData,findToken("TrnTkn"))]
		[abort(SPELL_LOOKUP_SPELLLIBRARY_NOT_FOUND)]
	}]
}]
[h: macro.return=tData]
[h: 'abort(DEBUG_Spell_Lookup_Lib_SpellLibrary)']

[h:objValue=macro.args]

[h:repeat=json.fields(objValue)]
[h:objText=""]


[h,count(listcount(repeat)),code:{

	[h:key=listget(repeat,roll.count)]
	[h:value=json.get(objValue,key)]


	[h,if(listcount(repeat)==roll.count+1):indexId=-1;indexId=roll.count+1]

	[h,switch(indexId):
	case -1:objText=objText+if(objText!=""," and ","")+value;
	case 1:objText=value;
	default:objText=objText+if(objText!="",", ","")+value]
}]

[h:macro.return=objText]

[h: this = getMacroLocation()]
[h:obj=getStrProp(macro.args,"obj")]
[h:group=getStrProp(macro.args,"group")]



[h,if(json.type(obj)=="UNKNOWN"),code:{

	[h:group=group+"

"+obj]

};{

	[h:type=json.get(obj,"type")]

	[h,switch(type),code:
	case "entries":{


		[macro("RenderEntries@"+this):obj]
		[h:obj=macro.return]




	};
	case "table":{

		[macro("RenderTable@"+this):obj]
		[h:obj=macro.return]

	};

	default:{

		[macro("RenderList@"+this):obj]
		[h:obj=macro.return]

	}]

	[h:group=group+"

"+obj]

}]

[h:macro.return=group]

