		}]
		[h, if(json.contains(filePath,"error") || filePath == ""),CODE:{
			[h: tParse = ""]
			[h: allDataJSON = ""]
		}]
	};
	case "_legObj":{
		[h, if(bookTokenID!=""): filePath = getProperty(thisProp,bookTokenID,libMap) ; filePath = REST.get(FiveETools+"/data/bestiary/legendarygroups.json")]
		[h, if(batchBuild!=0 && !json.contains(filePath,"error") && bookTokenID=="" || bookDL && !json.contains(filePath,"error")),CODE:{	
