		}]

		[h, if(json.contains(filePath,"error") || filePath == ""),CODE:{
			[h: tParse = ""]
			[h: allDataJSON = ""]
		}]
	};
	default: {
		[h: tParse = ""]
	}
]

[h, if(tParse !="" && !json.contains(filePath,"error")),CODE:{	
