[h, if(macGroup=="spells"), foreach(oneEntry,parseJSON),CODE:{
	[h, if(json.contains(oneEntry,"name")):name = json.get(oneEntry,"name") ; name = oneEntry]
	[h, if(startsWith(name,"x")): name = substring(name,1)]
	[h, if(json.contains(oneEntry,"name")): command = '[h, macro("Process Macro@Lib:MonsterMaker"):json.append("","'+btnMacName+'Note","'+json.get(oneEntry,"name")+'",currentToken(),"'+json.get(oneEntry,"spellText")+'")]' ; command = ""]
	[h, if(command!=""): macroProps = json.set(macroProps,
		"color",legendaryColor,
		"sortBy","0.1",
		"fontColor","black",
		"tooltip","Spellcasting Ability")
		; macroProps = json.set(macroProps,
		"color",json.get(spellColors,substring(oneEntry,(indexOf(oneEntry,"(")+1),indexOf(oneEntry,")"))),
		"sortBy",roll.count,
		"fontColor",if(indexOf("6,7,8,9",substring(oneEntry,(indexOf(oneEntry,"(")+1),indexOf(oneEntry,")")))>=0,"white","black"),
		"tooltip","Cast a Spell")]
[h, if(indexOf(name,"{@recharge")>=0),CODE:{
		[h: name = substring(name,0,indexOf(name,"{@recharge"))]
		[h: addCommand = strFormat('	[h, macro("rollDie@Lib:MonsterMaker"):"1d6"]
	[h: rDie = json.get(macro.return,"rolledTotal")]
    [h, if(isFunctionDefined("rollDO")),CODE:{
    	[h: diceThrown = json.get(macro.return,"diceThrown")]
		[h: tokDiceProp = getLibProperty("LibDiceOverlay","lib:"+getPlayerName())]
    };{
    	[h: diceThrown = ""]
    	[h: tokDiceProp = ""]
    }]
    [h, if(rDie >= 5), CODE:{
        [h: cdLabel = json.set("{}", "label", "'+name+'", "color", "'+legendaryColor+'","tooltip","<html><b>'+name+' is recharged</b><br>Perform '+name+' action!</html>")]
        [h: outputText = "Rolled: "+rDie+" - '+name+' has been refreshed"]
      };{
        [h: cdLabel = json.set("{}", "tooltip","'+name+' still on cooldown")]
        [h: outputText = "Rolled: "+rDie+" - '+name+' still on cooldown"]
    }]
