  font-style: italic;
}
.property-block{
  padding: 10px 2px 0;
}

a:link, a:visited {
  color: blue;	
  text-align: right;
  text-decoration: none;
}
a:hover, a:active {
  color: green;
}

body {
  text-align: center;
  font-size: 13.5px;
  line-height: 1.2em;
  margin-right: 1.5%;
}
body *{
  box-sizing: border-box;
  max-width: 100%;
  font-family: 'Noto Sans', 'Myriad Pro', Calibri, Helvetica,
    Arial, sans-serif;
}

.stat-block {
  text-align: left;
  display: inline-block;
  vertical-align: top;
  width: 100%;
  min-width:400px;
  padding: 5px 10px 20px;
  box-shadow: 0 0 1.5em #867453;
}

.section-left{
  display: inline-block;
  vertical-align: top;
  width: 96%;
  text-align: left;
}
.orange-border{
  display: block;
  background: #E69A28;
  border: 1px solid #000;
  height: 5px;
  padding: 0 10px 0;
  margin: -10px -10px 0;
  box-sizing: initial;
}
.orange-border.bottom{
  margin: 15px -10px -20px;
}
.tapered-rule{
  display: block;
  width: 100%;
  height: 5px;
  border: none;
  fill: #922610;
  stroke: #922610;
}
.creature-heading h1{
  font-family: 'Libre Baskerville', 'Lora', 'Calisto MT', 'Bookman Old Style', Bookman, 'Goudy Old Style', Garamond, 'Hoefler Text', 'Bitstream Charter', Georgia, serif;

  font-size: 23px;
  line-height: 1.2em;
  margin: 10px 0 0;
  letter-spacing: 1px;
  font-variant: small-caps;
  font-weight: bold;
}
.creature-heading h2{
  font-weight: normal;
  font-style: italic;
  font-size: 12px;
  line-height: 1.2em;
  margin: 0 0 10px;
}

.property-line h4,
.property-line p{
  display: inline;
  margin: 0;
  font-size: 13.5px;
  line-height: 1.2em;
}
.property-line{
  margin: 1px 0 0;
  text-indent: -1em;
  padding-left: 1.1em;
  line-height: 1.4em;
}
.property-line.first{
  margin: 8px 0 0
}
.property-line.last{
  margin: 0 0 8px;
}

.abilities{
  text-align: center;
}
.abilities div{
  display: inline-block;
  vertical-align: middle;  
  text-align: center;
  width: 12.5%;
  min-width: 40px; 
  font-size: 12px;
  line-height: 1em;
}
.tlink {
	  margin: 0px;
	  font-size: 9pt;
	  color: #922610;
}
.rlink {
	  font-size: 9pt;
	  color: #922610;
}
.rlink-top {
	  padding-top: 3px; 
  	  text-align: center;
	  font-size: 9pt;
	  color: #922610;
}

.abilities h4{
  padding-top: -10px;
  margin: 0 0 2px;
  font-size: 14px;
  line-height: 1.2em;
  text-transform: uppercase;
}
.abilities p{
  margin: 0 0 0 0;
  line-height: 1.2em;
}
.property-block h4,
.property-block p{
  font-size: 13.5px;
