[r: vMsg]

[h:objValue=macro.args]

[h:repeat=json.fields(objValue)]
[h:objText=""]


[h,count(listcount(repeat)),code:{

	[h:key=listget(repeat,roll.count)]
	[h:value=json.get(objValue,key)]


	[h,if(listcount(repeat)==roll.count+1):indexId=-1;indexId=roll.count+1]

	[h,switch(indexId):
	case -1:objText=objText+if(objText!=""," and ","")+value;
	case 1:objText=value;
	default:objText=objText+if(objText!="",", ","")+value]
}]

[h:macro.return=objText]

[h: this = getMacroLocation()]
[h:obj=getStrProp(macro.args,"obj")]
[h:group=getStrProp(macro.args,"group")]



[h,if(json.type(obj)=="UNKNOWN"),code:{

	[h:group=group+"

"+obj]

};{

	[h:type=json.get(obj,"type")]

	[h,switch(type),code:
	case "entries":{


		[macro("RenderEntries@"+this):obj]
		[h:obj=macro.return]




	};
	case "table":{

		[macro("RenderTable@"+this):obj]
		[h:obj=macro.return]

	};

	default:{

		[macro("RenderList@"+this):obj]
		[h:obj=macro.return]

	}]

	[h:group=group+"

"+obj]

}]

[h:macro.return=group]

[h: tokenRef = getMacroLocation()]
[h, if(startsWith(tokenRef,"Token:")),CODE:{
	[h: tokenRef = findToken(getSelected())]
	[h, if(listCount(tokenRef)>1 || tokenRef==""):return(0)]
}]
[h: tMacro=getMacroButtonIndex()]
[h: tGroup=json.get(getMacroProps(tMacro,"json",tokenRef),"group")]
[h: tMacroIDs=getMacroGroup(tGroup,",",tokenRef)]
[h: vThisMacro = getMacroName()]
[h: vExpandedLabel  = "Collapse "+tGroup]
[h: vCollapsedLabel = "Expand "+tGroup]
[h: vMacID = getMacroButtonIndex()]
[h: vThisMacroProps = getMacroProps(getMacroButtonIndex(),",",tokenRef)]
[h, if(matches(vThisMacro, vExpandedLabel) || matches(vThisMacro, "Collapse")), code: {
	[h: setMacroProps(getMacroButtonIndex(), json.set("{}", "label", vCollapsedLabel), "json",tokenRef)]
	[h: expand = 1]
};{
	[h: setMacroProps(getMacroButtonIndex(), json.set("{}", "label", vExpandedLabel), "json",tokenRef)]
	[h: expand = 0]
}]
[h, foreach(tMacro,tMacroIDs), CODE:{
	[h: macJSON = getMacroProps(tMacro,"json",tokenRef)]
	[h: maxWidth = ""]
	[h: json.toVars(macJSON)]
	[h, if(expand),CODE:{
		[h: 'grow stuff']
		[h: json.toVars(maxWidth)]
		[h: macJSON = ""]
		[h: setMacroProps(tMacro, json.set("{}", "maxWidth", macJSON,"fontSize", fsize,"minWidth", width), "json",tokenRef)]
	};{
		[h: 'shrink stuff']
		[h: macJSON = json.set("","width",minWidth,"fsize",fontSize)]
		[h: setMacroProps(tMacro, json.set("{}", "maxWidth", macJSON), "json",tokenRef)]
		[h: minWidth = "0"]
		[h: fontSize = "0.0em"]
		[h, if(tMacro != vMacID): setMacroProps(tMacro, json.set("{}", "fontSize", fontSize,"minWidth", minWidth), "json",tokenRef)]
	}]
}]

