	[h, foreach(oneTarget,tokenIDs),CODE:{
		[h, if(hasProperty("Initiative",oneTarget)): tInit= 1d20 + getProperty("Initiative",oneTarget) ; tInit = 1d20]
		[h: mOutput= strformat('<div style="background-color: blue; color: #FFFFFF; padding-top:2px; padding-bottom:1px; padding-left:5px; padding-right:5px;"><b> '+getName(oneTarget)+'- Initiative </b><div style="background-color:#FFFFFF; color: #000000; padding:2px;">'+getName(oneTarget)+' rolls initiative: '+tInit+'</div></div>')]
		[h: addToInitiative(0,tInit,oneTarget)]
		[h: broadcast(mOutput,chatList)]
	}]
	[h, if(indexOf(libTokens,"Lib:InitOverlay")>=0),CODE:{
		[h, macro("Initiative Render@Lib:InitOverlay"):""]
	}]

	[h: sortInitiative()]
}]

[h, if(getInitiativeToken() == currentToken()), code: { 
	[h: message = add(token.name, " ends its turn.")] 
	[h: broadcast(message)] 
	[h: nextInitiative()]
};{
	[h: message = add("<i style='color:gray;'>It is not ", token.name, "'s turn!</i>")]
	[h: broadcast(message, getPlayerName(), "gm")]
}]

[h: this = getMacroLocation()]
[h: thisProp = "Lib"+listGet(this,1,":")]
[h: libJSON = getLibProperty(thisProp,this)]
[h: tParse = macro.args]
[h: json.toVars(libJSON)]
[h: json.toVars(MMsettings)]

[h, if(startsWith(tParse,"_copy_")),CODE:{
	[h: bookName = substring(tParse,6)]
	[h: tParse = "_copy"]
}]
[h, if(startsWith(tParse,"_leg")): bookName = "Legendary Groups"]

[h: FiveETools = "https://5e.tools"]

[h: bookTokenID = findToken(bookName,libMap)]
[h, if(bookTokenID!=""), CODE:{
	[h, if(!hasProperty(thisProp,bookTokenID,libMap)): bookTokenID = ""]
}]
[h, if(bookTokenID==""): bookTokenID = findToken("MMBook-"+bookName,libMap)]

[h, switch(tParse),CODE:
	case "_copy":{
		[h, if(bookTokenID!=""): filePath = getProperty(thisProp,bookTokenID,libMap) ; filePath = REST.get(FiveETools+"/data/bestiary/"+copyfileName)]
		[h, if(batchBuild!=0 && !json.contains(filePath,"error") && bookTokenID==""),CODE:{	
			[h, macro("createBookToken@"+this):json.append("",bookName,filePath)]
		}]
		[h, if(json.contains(filePath,"error") || filePath == ""),CODE:{
			[h: tParse = ""]
			[h: allDataJSON = ""]
		}]
	};
	case "_legObj":{
		[h, if(bookTokenID!=""): filePath = getProperty(thisProp,bookTokenID,libMap) ; filePath = REST.get(FiveETools+"/data/bestiary/legendarygroups.json")]
		[h, if(batchBuild!=0 && !json.contains(filePath,"error") && bookTokenID=="" || bookDL && !json.contains(filePath,"error")),CODE:{	
			[h, macro("createBookToken@"+this):json.append("","Legendary Groups",filePath)]
		}]

		[h, if(json.contains(filePath,"error") || filePath == ""),CODE:{
			[h: tParse = ""]
			[h: allDataJSON = ""]
		}]
	};
	default: {
		[h: tParse = ""]
	}
]

[h, if(tParse !="" && !json.contains(filePath,"error")),CODE:{	
		[h: libJSON = json.set(libJSON,"copyJSON",filePath)]
		[h: setLibProperty(thisProp,libJSON,this)]
		[h: deferLink = macroLinkText("getTokenData@"+this,"none",tParse)]
		[h, macro("delayMS@Lib:MonsterMaker"):json.append("",deferLink,500)]
};{
		[h: formHTML = strformat('
		    <div style="text-align:center">
		    <br>
		    MonsterMaker<br>
		    Gathering Book information . . . <br><br>
		    '+if(!json.contains(allDataJSON,"monster"),"No Monster Data Found!!","Failed gettting REST data!!")+'<br>
		    <i>Restarting . . . </i>
		    </div>')]
		[h, macro("updateDialog@this"):json.append("",formHTML,400,250)]

	[h: deferLink = macroLinkText("BatchBuild@"+this,"none","","")]
	[macro("delayMS@Lib:MonsterMaker"):json.append("",deferLink,5000)]
}]
[h: abort(0)]

[h: alignmentArray=macro.args]
[h: alignmentList = json.toList(alignmentArray)]

[h: alignment = ""]
[h,switch(listcount(alignmentList)),code:
	case 6:{
		[h,foreach(oneItem,alignmentArray),CODE:{
			[h: oneList = json.toList(json.get(oneItem,"alignment"))]
			[h, if(roll.count>0): alignment = alignment + " or "]
			[h,if(indexOf(oneList,"C")>=0):alignment = alignment + "Chaotic "]
			[h,if(indexOf(oneList,"N")>=0):alignment = alignment + "Neutral "]
			[h,if(indexOf(oneList,"L")>=0):alignment = alignment + "Lawful "]
			[h,if(indexOf(oneList,"G")>=0):alignment = alignment + "Good Alignment"]
			[h,if(indexOf(oneList,"E")>=0):alignment = alignment + "Evil Alignment"]
			[h,if(json.contains(oneItem,"chance")): alignment = alignment + " (" + json.get(oneItem,"chance")+"%)"]
		}]

	};
	case 5:{

		[h,if(matches(alignmentList,".*C.*")==0):alignment = "Any Non-Chaotic Alignment"]
		[h,if(matches(alignmentList,".*L.*")==0):alignment = "Any Non-Lawful Alignment"]
		[h,if(matches(alignmentList,".*G.*")==0):alignment = "Any Non-Good Alignment"]
		[h,if(matches(alignmentList,".*E.*")==0):alignment = "Any Non-Evil Alignment"]

	};
	case 4:{
		[h,if(matches(alignmentList,".*NX.*")==1 && matches(alignmentList,".*NY.*")==0):alignment = "Any Evil Alignment"]
		[h,if(matches(alignmentList,".*NX.*")==0 && matches(alignmentList,".*NY.*")==0):alignment = "Any Good Alignment"]
		[h,if(matches(alignmentList,".*NY.*")==1 && matches(alignmentList,".*NX.*")==0):alignment = "Any Chaotic Alignment"]
		[h,if(matches(alignmentList,".*NY.*")==0 && matches(alignmentList,".*NX.*")==0):alignment = "Any Lawful Alignment"]

	};

	case 2:{
		[h,switch(listget(alignmentList,0)):
		case "L":alignment = "Lawful";
		case "C":alignment = "Chaotic";
		default:alignment = "Neutral"]

		[h,switch(listget(alignmentList,1)):
		case "G":alignment = alignment+" Good";
		case "E":alignment = alignment+" Evil";
		default:alignment = "Neutral"]

	};
	default:{
		[h,if(matches(alignmentList,".*NX.*")==1 && matches(alignmentList,".*NY.*")==0):alignment = "Any Evil Alignment"]
		[h,if(matches(alignmentList,".*NX.*")==0 && matches(alignmentList,".*NY.*")==0):alignment = "Any Good Alignment"]
		[h,if(matches(alignmentList,".*NY.*")==1 && matches(alignmentList,".*NX.*")==0):alignment = "Any Chaotic Alignment"]
		[h,if(matches(alignmentList,".*NY.*")==0 && matches(alignmentList,".*NX.*")==0):alignment = "Any Lawful Alignment"]
		[h, if(json.contains(alignmentList,"special")): tAlignmentList = "" ; tAlignmentList = alignmentList]
		[h,switch(listget(tAlignmentList,0)):
			case "U":alignment = "Unaligned";
			case "N":alignment = "Neutral";
			default: alignment = "Any Alignment"
		]
		[h, if(alignment == "Any Alignment" && json.contains(alignmentList,"special")): alignment = json.get(alignmentList,"special")]
	}
]


[h: macro.return=alignment]

[h: libTokens = json.path.read(getInfo("client"),"['library tokens']")]
[h: spellName = listget(json.get(macro.args,0),1,":")]

[h, if(json.contains(libTokens,"Lib:SpellLibrary") && spellName!=""),CODE:{
	[macro("Show a Spell@Lib:SpellLibrary"):lower(spellName)]
}]

[h: speedObj = macro.args]

[h, if(json.contains(speedObj,"canHover")): speedObj = json.remove(speedObj,"canHover")]

[h: repeat = json.fields(speedObj)]

[h: speed = ""]
[h,count(listcount(repeat)),code:{
	[h: currentMovement = listget(repeat,roll.count)]
	[h: SpeedValue = json.get(speedObj,currentMovement)]
	[h,if(json.type(SpeedValue)=="OBJECT"),code:{

		[h: speedCondition = json.get(SpeedValue,"condition")]
		[h: SpeedValue = json.get(SpeedValue,"number")]
		[h: SpeedText = SpeedValue+" ft. "+speedCondition]

	};{
		[h: SpeedText = SpeedValue]
	}]

	[h: speed = listappend(speed,if(currentMovement=="walk","",currentMovement+" ")+SpeedText)]

}]
[h: macro.return = speed]

[h: size = macro.args]
[h,switch(size):
case "T":size = "Tiny";
case "S":size = "Small";
case "M":size = "Medium";
case "L":size = "Large";
case "H":size = "Huge";
case "G":size = "Gargantuan";
default:size = "Unknown"]
[h: macro.return = size]

[h: this = getMacroLocation()]

[h: resistances = macro.args]

[h: repeat = json.fields(resistances)]

[h: resistText = ""]
[h,count(listcount(repeat)),code:{

	[h: key = listget(repeat,roll.count)]
	[h: value = json.get(resistances,key)]

	[h,switch(json.type(value)),code:
	case "OBJECT":{

		[h: objValue = json.get(value,"resist")]
		[h: note = json.get(value,"note")]

		[h,macro("getObjList@"+this):objValue]
		[h: objValue = macro.return]
		[h, if(json.contains(value,"preNote")): objValue = json.get(value,"preNote")+" "+objValue] 
		[h, if(json.contains(value,"special")): objValue = json.get(value,"special") ; objValue = "; "+objValue]
		[h: resistText = resistText+objValue+" "+note]


	};
	default:{

		[h: resistText = if(roll.count==0,value,resistText+", "+value)]

	}]
}]

[h: macro.return=resistText]

[h: this = getMacroLocation()]
[h: DMGimmunities = macro.args]

[h: repeat = json.fields(DMGimmunities)]

[h: resistText = ""]
[h,count(listcount(repeat)),code:{

	[h: key = listget(repeat,roll.count)]
	[h: value = json.get(DMGimmunities,key)]

	[h,switch(json.type(value)),code:
	case "OBJECT":{

		[if(json.contains(value,"conditionImmune")): objValue = json.get(value,"conditionImmune") ; objValue = json.get(value,"immune")]
		[note = json.get(value,"note")]

		[h,macro("getObjList@"+this):objValue]
		[h: objValue = macro.return]

		[h: resistText = resistText+if(resistText!="","; ","")+upper(objValue,1)+" "+note]


	};
	default:{

		[h: resistText = if(roll.count==0,upper(value,1),resistText+", "+upper(value,1))]

	}]

}]

[h: macro.return=resistText]

[h: hpObj = macro.args]

[h, if(json.contains(hpObj,"special")),CODE:{
	[h: formula = json.get(hpObj,"special")]	
	[h, if(indexOf(formula," ")>=0), CODE:{
		[h:average = substring(formula,0,indexOf(formula," "))]
	};{
		[h: average = formula]
		[h: formula = ""]
	}]
};{
	[h, if(json.length(hpObj)<=1),CODE:{
		[h: average = hpObj]
		[h: formula = ""]
	};{
		[h: average = json.get(hpObj,"average")]
		[h: formula = json.get(hpObj,"formula")]
	}]
}]
[h: macro.return=json.set("","hp",average,"hd",formula)]

[h, if(argCount()<3):return(0,"")]
[h: skill = json.get(macro.args,0)]
[h: rollType = json.get(macro.args,1)]
[h: tokenID = json.get(macro.args,2)]
[h: this = getMacroLocation()]
[h: skillHTML = ""]
[h,foreach(oneItem,skill),CODE:{
    [h: skillValue = json.get(skill,oneItem)+" "]
    [switch(oneItem):
 		  case "acrobatics": skillTitle ="Your&nbsp;Dexterity&nbsp;(Acrobatics)&nbsp;check&nbsp;covers&nbsp;your&nbsp;attempt&nbsp;to&nbsp;stay&nbsp;on&nbsp;your&nbsp;feet&nbsp;in&nbsp;a&nbsp;tricky&#013;situation,&nbsp;such&nbsp;as&nbsp;when&nbsp;you&#39;re&nbsp;trying&nbsp;to&nbsp;run&nbsp;across&nbsp;a&nbsp;sheet&nbsp;of&nbsp;ice,&nbsp;balance&nbsp;on&nbsp;a&nbsp;tightrope,&#013;or&nbsp;stay&nbsp;upright&nbsp;on&nbsp;a&nbsp;rocking&nbsp;ship&#39;s&nbsp;deck.&nbsp;The&nbsp;DM&nbsp;might&nbsp;also&nbsp;call&nbsp;for&nbsp;a&nbsp;Dexterity&#013;(Acrobatics)&nbsp;check&nbsp;to&nbsp;see&nbsp;if&nbsp;you&nbsp;can&nbsp;perform&nbsp;acrobatic&nbsp;stunts,&nbsp;including&nbsp;dives,&nbsp;rolls,&#013;somersaults,&nbsp;and&nbsp;flips.";
 		  case "animal handling": skillTitle = "When&nbsp;there&nbsp;is&nbsp;any&nbsp;question&nbsp;whether&nbsp;you&nbsp;can&nbsp;calm&nbsp;down&nbsp;a&nbsp;domesticated&nbsp;animal,&nbsp;keep&nbsp;a&nbsp;mount&#013;from&nbsp;getting&nbsp;spooked,&nbsp;or&nbsp;intuit&nbsp;an&nbsp;animal&#39;s&nbsp;intentions,&nbsp;the&nbsp;DM&nbsp;might&nbsp;call&nbsp;for&nbsp;a&nbsp;Wisdom&#013;(Animal&nbsp;Handling)&nbsp;check.&nbsp;You&nbsp;also&nbsp;make&nbsp;a&nbsp;Wisdom&nbsp;(Animal&nbsp;Handling)&nbsp;check&nbsp;to&nbsp;control&nbsp;your&#013;mount&nbsp;when&nbsp;you&nbsp;attempt&nbsp;a&nbsp;risky&nbsp;maneuver.";
 		  case "arcana": skillTitle ="Your&nbsp;Intelligence&nbsp;(Arcana)&nbsp;check&nbsp;measures&nbsp;your&nbsp;ability&nbsp;to&nbsp;recall&nbsp;lore&nbsp;about&nbsp;spells,&nbsp;magic&#013;items,&nbsp;eldritch&nbsp;symbols,&nbsp;magical&nbsp;traditions,&nbsp;the&nbsp;planes&nbsp;of&nbsp;existence,&nbsp;and&nbsp;the&nbsp;inhabitants&nbsp;of&#013;those&nbsp;planes.";
 		  case "athletics": skillTitle = "Your&nbsp;Strength&nbsp;(Athletics)&nbsp;check&nbsp;covers&nbsp;difficult&nbsp;situations&nbsp;you&nbsp;encounter&nbsp;while&nbsp;climbing,&#013;jumping,&nbsp;or&nbsp;swimming.&nbsp;Examples&nbsp;include&nbsp;the&nbsp;following&nbsp;activities:&#013;&#013;You&nbsp;attempt&nbsp;to&nbsp;climb&nbsp;a&nbsp;sheer&nbsp;or&nbsp;slippery&nbsp;cliff,&nbsp;avoid&nbsp;hazards&nbsp;while&nbsp;scaling&nbsp;a&nbsp;wall,&nbsp;or&nbsp;cling&#013;to&nbsp;a&nbsp;surface&nbsp;while&nbsp;something&nbsp;is&nbsp;trying&nbsp;to&nbsp;knock&nbsp;you&nbsp;off.&#013;You&nbsp;try&nbsp;to&nbsp;jump&nbsp;an&nbsp;unusually&nbsp;long&nbsp;distance&nbsp;or&nbsp;pull&nbsp;off&nbsp;a&nbsp;stunt&nbsp;mid&nbsp;jump.&#013;You&nbsp;struggle&nbsp;to&nbsp;swim&nbsp;or&nbsp;stay&nbsp;afloat&nbsp;in&nbsp;treacherous&nbsp;currents,&nbsp;storm-tossed&nbsp;waves,&nbsp;or&nbsp;areas&nbsp;of&#013;thick&nbsp;seaweed.&nbsp;Or&nbsp;another&nbsp;creature&nbsp;tries&nbsp;to&nbsp;push&nbsp;or&nbsp;pull&nbsp;you&nbsp;underwater&nbsp;or&nbsp;otherwise&nbsp;interfere&#013;with&nbsp;your&nbsp;swimming.";
 		  case "deception": skillTitle = "Your&nbsp;Charisma&nbsp;(Deception)&nbsp;check&nbsp;determines&nbsp;whether&nbsp;you&nbsp;can&nbsp;convincingly&nbsp;hide&nbsp;the&nbsp;truth,&#013;either&nbsp;verbally&nbsp;or&nbsp;through&nbsp;your&nbsp;actions.&nbsp;This&nbsp;deception&nbsp;can&nbsp;encompass&nbsp;everything&nbsp;from&#013;misleading&nbsp;others&nbsp;through&nbsp;ambiguity&nbsp;to&nbsp;telling&nbsp;outright&nbsp;lies.&nbsp;Typical&nbsp;situations&nbsp;include&#013;trying&nbsp;to&nbsp;fast-talk&nbsp;a&nbsp;guard,&nbsp;con&nbsp;a&nbsp;merchant,&nbsp;earn&nbsp;money&nbsp;through&nbsp;gambling,&nbsp;pass&nbsp;yourself&nbsp;off&nbsp;in&#013;a&nbsp;disguise,&nbsp;dull&nbsp;someone&#39;s&nbsp;suspicions&nbsp;with&nbsp;false&nbsp;assurances,&nbsp;or&nbsp;maintain&nbsp;a&nbsp;straight&nbsp;face&nbsp;while&#013;telling&nbsp;a&nbsp;blatant&nbsp;lie.";
 		  case "history": skillTitle = "Your&nbsp;Intelligence&nbsp;(History)&nbsp;check&nbsp;measures&nbsp;your&nbsp;ability&nbsp;to&nbsp;recall&nbsp;lore&nbsp;about&nbsp;historical&#013;events,&nbsp;legendary&nbsp;people,&nbsp;ancient&nbsp;kingdoms,&nbsp;past&nbsp;disputes,&nbsp;recent&nbsp;wars,&nbsp;and&nbsp;lost&#013;civilizations.";
 		  case "insight": skillTitle = "Your&nbsp;Wisdom&nbsp;(Insight)&nbsp;check&nbsp;decides&nbsp;whether&nbsp;you&nbsp;can&nbsp;determine&nbsp;the&nbsp;true&nbsp;intentions&nbsp;of&nbsp;a&#013;creature,&nbsp;such&nbsp;as&nbsp;when&nbsp;searching&nbsp;out&nbsp;a&nbsp;lie&nbsp;or&nbsp;predicting&nbsp;someone&#39;s&nbsp;next&nbsp;move.&nbsp;Doing&nbsp;so&#013;involves&nbsp;gleaning&nbsp;clues&nbsp;from&nbsp;body&nbsp;language,&nbsp;speech&nbsp;habits,&nbsp;and&nbsp;changes&nbsp;in&nbsp;mannerisms.";
 		  case "intimidation": skillTitle = "When&nbsp;you&nbsp;attempt&nbsp;to&nbsp;influence&nbsp;someone&nbsp;through&nbsp;overt&nbsp;threats,&nbsp;hostile&nbsp;actions,&nbsp;and&nbsp;physical&#013;violence,&nbsp;the&nbsp;DM&nbsp;might&nbsp;ask&nbsp;you&nbsp;to&nbsp;make&nbsp;a&nbsp;Charisma&nbsp;(Intimidation)&nbsp;check.&nbsp;Examples&nbsp;include&#013;trying&nbsp;to&nbsp;pry&nbsp;information&nbsp;out&nbsp;of&nbsp;a&nbsp;prisoner,&nbsp;convincing&nbsp;street&nbsp;thugs&nbsp;to&nbsp;back&nbsp;down&nbsp;from&nbsp;a&#013;confrontation,&nbsp;or&nbsp;using&nbsp;the&nbsp;edge&nbsp;of&nbsp;a&nbsp;broken&nbsp;bottle&nbsp;to&nbsp;convince&nbsp;a&nbsp;sneering&nbsp;vizier&nbsp;to&#013;reconsider&nbsp;a&nbsp;decision.";
 		  case "investigation": skillTitle = "When&nbsp;you&nbsp;look&nbsp;around&nbsp;for&nbsp;clues&nbsp;and&nbsp;make&nbsp;deductions&nbsp;based&nbsp;on&nbsp;those&nbsp;clues,&nbsp;you&nbsp;make&nbsp;an&#013;Intelligence&nbsp;(Investigation)&nbsp;check.&nbsp;You&nbsp;might&nbsp;deduce&nbsp;the&nbsp;location&nbsp;of&nbsp;a&nbsp;hidden&nbsp;object,&nbsp;discern&#013;from&nbsp;the&nbsp;appearance&nbsp;of&nbsp;a&nbsp;wound&nbsp;what&nbsp;kind&nbsp;of&nbsp;weapon&nbsp;dealt&nbsp;it,&nbsp;or&nbsp;determine&nbsp;the&nbsp;weakest&nbsp;point&nbsp;in&#013;a&nbsp;tunnel&nbsp;that&nbsp;could&nbsp;cause&nbsp;it&nbsp;to&nbsp;collapse.&nbsp;Poring&nbsp;through&nbsp;ancient&nbsp;scrolls&nbsp;in&nbsp;search&nbsp;of&nbsp;a&nbsp;hidden&#013;fragment&nbsp;of&nbsp;knowledge&nbsp;might&nbsp;also&nbsp;call&nbsp;for&nbsp;an&nbsp;Intelligence&nbsp;(Investigation)&nbsp;check.";
 		  case "medicine": skillTitle = "A&nbsp;Wisdom&nbsp;(Medicine)&nbsp;check&nbsp;lets&nbsp;you&nbsp;try&nbsp;to&nbsp;stabilize&nbsp;a&nbsp;dying&nbsp;companion&nbsp;or&nbsp;diagnose&nbsp;an&nbsp;illness.";
 		  case "nature": skillTitle = "Your&nbsp;Intelligence&nbsp;(Nature)&nbsp;check&nbsp;measures&nbsp;your&nbsp;ability&nbsp;to&nbsp;recall&nbsp;lore&nbsp;about&nbsp;terrain,&nbsp;plants&#013;and&nbsp;animals,&nbsp;the&nbsp;weather,&nbsp;and&nbsp;natural&nbsp;cycles.";
 		  case "perception": skillTitle = "Your&nbsp;Wisdom&nbsp;(Perception)&nbsp;check&nbsp;lets&nbsp;you&nbsp;spot,&nbsp;hear,&nbsp;or&nbsp;otherwise&nbsp;detect&nbsp;the&nbsp;presence&nbsp;of&#013;something.&nbsp;It&nbsp;measures&nbsp;your&nbsp;general&nbsp;awareness&nbsp;of&nbsp;your&nbsp;surroundings&nbsp;and&nbsp;the&nbsp;keenness&nbsp;of&nbsp;your&#013;senses.&#013;&#013;For&nbsp;example,&nbsp;you&nbsp;might&nbsp;try&nbsp;to&nbsp;hear&nbsp;a&nbsp;conversation&nbsp;through&nbsp;a&nbsp;closed&nbsp;door,&nbsp;eavesdrop&nbsp;under&nbsp;an&#013;open&nbsp;window,&nbsp;or&nbsp;hear&nbsp;monsters&nbsp;moving&nbsp;stealthily&nbsp;in&nbsp;the&nbsp;forest.&nbsp;Or&nbsp;you&nbsp;might&nbsp;try&nbsp;to&nbsp;spot&nbsp;things&#013;that&nbsp;are&nbsp;obscured&nbsp;or&nbsp;easy&nbsp;to&nbsp;miss,&nbsp;whether&nbsp;they&nbsp;are&nbsp;orcs&nbsp;lying&nbsp;in&nbsp;ambush&nbsp;on&nbsp;a&nbsp;road,&nbsp;thugs&#013;hiding&nbsp;in&nbsp;the&nbsp;shadows&nbsp;of&nbsp;an&nbsp;alley,&nbsp;or&nbsp;candlelight&nbsp;under&nbsp;a&nbsp;closed&nbsp;secret&nbsp;door.";
 		  case "performance": skillTitle = "Your&nbsp;Charisma&nbsp;(Performance)&nbsp;check&nbsp;determines&nbsp;how&nbsp;well&nbsp;you&nbsp;can&nbsp;delight&nbsp;an&nbsp;audience&nbsp;with&nbsp;music,&#013;dance,&nbsp;acting,&nbsp;storytelling,&nbsp;or&nbsp;some&nbsp;other&nbsp;form&nbsp;of&nbsp;entertainment.";
 		  case "persuasion": skillTitle = "When&nbsp;you&nbsp;attempt&nbsp;to&nbsp;influence&nbsp;someone&nbsp;or&nbsp;a&nbsp;group&nbsp;of&nbsp;people&nbsp;with&nbsp;tact,&nbsp;social&nbsp;graces,&nbsp;or&nbsp;good&#013;nature,&nbsp;the&nbsp;DM&nbsp;might&nbsp;ask&nbsp;you&nbsp;to&nbsp;make&nbsp;a&nbsp;Charisma&nbsp;(Persuasion)&nbsp;check.&nbsp;Typically,&nbsp;you&nbsp;use&#013;persuasion&nbsp;when&nbsp;acting&nbsp;in&nbsp;good&nbsp;faith,&nbsp;to&nbsp;foster&nbsp;friendships,&nbsp;make&nbsp;cordial&nbsp;requests,&nbsp;or&nbsp;exhibit&#013;proper&nbsp;etiquette.&nbsp;Examples&nbsp;of&nbsp;persuading&nbsp;others&nbsp;include&nbsp;convincing&nbsp;a&nbsp;chamberlain&nbsp;to&nbsp;let&nbsp;your&#013;party&nbsp;see&nbsp;the&nbsp;king,&nbsp;negotiating&nbsp;peace&nbsp;between&nbsp;warring&nbsp;tribes,&nbsp;or&nbsp;inspiring&nbsp;a&nbsp;crowd&nbsp;of&#013;townsfolk.";
 		  case "religion": skillTitle = "Your&nbsp;Intelligence&nbsp;(Religion)&nbsp;check&nbsp;measures&nbsp;your&nbsp;ability&nbsp;to&nbsp;recall&nbsp;lore&nbsp;about&nbsp;deities,&nbsp;rites&#013;and&nbsp;prayers,&nbsp;religious&nbsp;hierarchies,&nbsp;holy&nbsp;symbols,&nbsp;and&nbsp;the&nbsp;practices&nbsp;of&nbsp;secret&nbsp;cults.";
 		  case "sleight of hand": skillTitle = "Whenever&nbsp;you&nbsp;attempt&nbsp;an&nbsp;act&nbsp;of&nbsp;legerdemain&nbsp;or&nbsp;manual&nbsp;trickery,&nbsp;such&nbsp;as&nbsp;planting&nbsp;something&nbsp;on&#013;someone&nbsp;else&nbsp;or&nbsp;concealing&nbsp;an&nbsp;object&nbsp;on&nbsp;your&nbsp;person,&nbsp;make&nbsp;a&nbsp;Dexterity&nbsp;(Sleight&nbsp;of&nbsp;Hand)&nbsp;check.&#013;The&nbsp;DM&nbsp;might&nbsp;also&nbsp;call&nbsp;for&nbsp;a&nbsp;Dexterity&nbsp;(Sleight&nbsp;of&nbsp;Hand)&nbsp;check&nbsp;to&nbsp;determine&nbsp;whether&nbsp;you&nbsp;can&#013;lift&nbsp;a&nbsp;coin&nbsp;purse&nbsp;off&nbsp;another&nbsp;person&nbsp;or&nbsp;slip&nbsp;something&nbsp;out&nbsp;of&nbsp;another&nbsp;person&#39;s&nbsp;pocket.";
 		  case "stealth": skillTitle = "Make&nbsp;a&nbsp;Dexterity&nbsp;(Stealth)&nbsp;check&nbsp;when&nbsp;you&nbsp;attempt&nbsp;to&nbsp;conceal&nbsp;yourself&nbsp;from&nbsp;enemies,&nbsp;slink&#013;past&nbsp;guards,&nbsp;slip&nbsp;away&nbsp;without&nbsp;being&nbsp;noticed,&nbsp;or&nbsp;sneak&nbsp;up&nbsp;on&nbsp;someone&nbsp;without&nbsp;being&nbsp;seen&nbsp;or&#013;heard.";
