[h,foreach(mod,macro.args),CODE:{
	[h,switch(mod):
	case "1":mod=" -5";
	case "2":mod=" -4";
	case "3":mod=" -4";
	case "4":mod=" -3";
	case "5":mod=" -3";
	case "6":mod=" -2";
	case "7":mod=" -2";
	case "8":mod=" -1";
	case "9":mod=" -1";
	case "10":mod=" +0";
	case "11":mod=" +0";
	case "12":mod=" +1";
	case "13":mod=" +1";
	case "14":mod=" +2";
	case "15":mod=" +2";
	case "16":mod=" +3";
	case "17":mod=" +3";
	case "18":mod=" +4";
	case "19":mod=" +4";
	case "20":mod=" +5";
	case "21":mod=" +5";
	case "22":mod=" +6";
	case "23":mod=" +6";
	case "24":mod=" +7";
	case "25":mod=" +7";
	case "26":mod=" +8";
	case "27":mod=" +8";
	case "28":mod=" +9";
	case "29":mod=" +9";
	case "30":mod=" +10";
	default:mod=" +0"]
	[h,switch(roll.count):
	case 0:strmod = mod;
	case 1:dexmod = mod;
	case 2:conmod = mod;
	case 3:intmod = mod;
	case 4:wismod = mod;
	case 5:chamod = mod]
}]
