[h, if(getFindCount(diceID) == 0): return(0,"")]

[h: diceSet = "[]"]
[h: diceMods = "[]"]
[h: lastMatch = ""]

[h, for(match, 1, getFindCount(diceID)+1), CODE: {
    [h: fullMatch = getGroup(diceID,match,1)]
