    [h: numDice = replace(getGroup(diceID,match,3),"d","")]
    [h, if(sides == 100),CODE:{
    	[h: numDice = numDice*2]
    	[h: sides = 10]
    }]
    [h: mod = getGroup(diceID,match,4)]
