   	[h, if(mod != ""): diceMods = json.append(diceMods,mod)]
	[h, if(sides != ""): diceSet = json.append(diceSet, sides+","+if(startsWith(fullMatch,"-"),"-","")+numDice)]
	[h: lastMatch = fullMatch]
}]


