[h: macDebug = 0]
[h, if(macDebug): broadcast(getMacroName()+"^"+macro.args)]

[h: tParse = macro.args]

[h: this = getMacroLocation()]
[h: thisProp = "Lib"+listGet(this,1,":")]
[h: libJSON = getLibProperty(thisProp,this)]
[h: json.toVars(libJSON)]
[h: json.toVars(MMsettings)]
[h, if(lower(chatList)=="all" && lower(gmList)=="gm"),CODE:{
	[h: gmList = ""]
	[h: chatList = ""]
	[h, foreach(oneP, getAllPlayerNames()), if(isGM(oneP)): gmList = listAppend(gmList,oneP) ; chatList = listAppend(chatList,oneP)]
}]
[h: pName = getPlayerName()]

[h, if(isFunctionDefined("rollDO")): tokDiceProp = getLibProperty("LibDiceOverlay","lib:"+pName) ; tokDiceProp = ""]
[h, if(json.contains(tokDiceProp,"runAfter")),CODE:{
	[h: runAfter = json.get(tokDiceProp,"runAfter")]
	[h: tokDiceProp = json.remove(tokDiceProp,"runAfter")]
	[h: setLibProperty("LibDiceOverlay",tokDiceProp,"lib:"+pName)]
	[h, if(json.contains(runAfter,"player")): cName = json.get(runAfter,"player") ; cName = ""]
	[h: finalOutput = json.get(runAfter,"params")]
	[h, if(cName == pName),CODE:{
		[h, macro("scrubLinks@this"):json.append("noShare",finalOutput)]
		[h: sOutput = decode(macro.return)]
		[h, if(listFind(chatList,cName)>=0):chatList = listDelete(chatList,listFind(chatList,cName))]
	};{
		[h: sOutput = ""]
	}]
	[h, macro("scrubLinks@this"):json.append("full",finalOutput)]
	[h: pOutput = decode(macro.return)]
	[h: finalOutput = decode(finalOutput)]
	[h, if(opt_DCE && opt_COO && finalOutput!=""),CODE:{
		[h, if(opt_COO!=2 && chatList!="" && chatList!=gmList): broadcast(pOutput,chatList)]
		[h, if(opt_COO!=2 && cName!="" && sOutput!=""): broadcast(sOutput,cName)]
		[h, if(opt_COO==2): broadcast(pOutput,chatList)]
		[h: execFunction("broadcast",json.append("",finalOutput,"self"),1,gmList)]
	}]
	[h: return(0,"")]
};{
	[h, if(tokDiceProp!=""): libDice = 1 ; libDice = 0]
}]


[h, if(json.get(tParse,0)!=""),CODE:{
	[h: submit = json.get(tParse,0)]
};{
	[h: json.toVars(tParse)]
	[h, if(!json.contains(tParse,"submit")): submit = "none"]
	[h, if(!json.contains(tParse,"cName")): cName = ""]
	[h, if(json.contains(tParse,"hitJSON") && submit!="Share" && !startsWith(submit,"Select ")): submit = "hitJSON"]
}]

[h, if(!json.contains(tParse,"usedSS")): usedSS = 0]

[h: tokenIDs = getSelected()]
[h: allStates = json.path.read(getInfo("campaign"),".states..name")]

[h: tokenImp = getImpersonated(1)]
[h: attackerID = tokenImp]
[h, if(isGM() && tokenImp!=""),CODE:{
	[h, if(findToken(tokenImp)!=""): IamGM = if(getGMName(tokenImp)=="DM",1,0) ; IamGM = 0]
};{
	[h, if(submit=="hitJSON"),CODE:{
		[h: attackerID = json.get(decode(hitJSON),"attackerID")]
		[h: tokOwners = getOwners("json",attackerID)]
		[h: IamGM = if(json.indexOf(tokOwners,pName)>=0,1,if(isGM(),1,0))]
	};{
		[h: IamGM = isGM()]
	}]
	[h, if(0==1 && !IamGM && listFind(gmList,pName)>=0): IamGM = 1]
}]

[h, if(!IamGM):return(0)]



[h, if(macDebug),CODE:{
	[h: broadcast(submit)]
}]

[h: finalOutput = ""]
[h: fullDiceThrown = ""]

[h, switch(submit),CODE:
	case "Share":{
		[h, macro("scrubLinks@this"):json.append("full",pOutput)]
		[h: pOutput = decode(macro.return)]
		[h, if(listFind(chatList,cName)>=0):chatList = listDelete(chatList,listFind(chatList,cName))]
		[h, if(chatList==""): chatList = "self"]
		[h: broadcast(pOutput,chatList)]		
	};
	case "Select Fail":{
		[h, foreach(oneToken,chkFailIDs), if(findToken(oneToken)!=""),CODE:{
			[h: selectTokens(chkFailIDs,"",",")]
		}]
	};
	case "Select Success":{
		[h, foreach(oneToken,chkSuccessIDs), if(findToken(oneToken)!=""),CODE:{
			[h: selectTokens(chkSuccessIDs,"",",")]
		}]
	};
	case "hitJSON":{		
		[h, if(tokenIDs ==""):return(0)]
		[h: pOutput = decode(pOutput)]
		[h: json.toVars(decode(hitJSON))]
		[h, if(attackerID == json.get(tokenIDs,0) && json.length(tokenIDs)==1): abort(input("header|Hurting yourself?|-|LABEL|SPAN=TRUE"))]
		[h: attackDiceThrown = ""]
		[h: damageDiceThrown = ""]
		[h: damageSecDiceThrown = ""]
[h, if(macDebug),CODE:{	
	[h: broadcast(decode(hitJSON))]
	[h: broadcast("opt_ATO "+opt_ATO)]
	[h: broadcast("opt_RDG "+opt_RDG)]
}]
		[h, if(json.contains(allStates,"Advantage") && json.contains(allStates,"Disadvantage") && rollType=="Roll"),CODE:{
			[h, if(getState("Advantage",attackerID)):rollAKType = "a"]
			[h, if(getState("Disadvantage",attackerID)):rollAKType = "x"]
		};{
			[h, switch(rollType):
				case "Adv":rollAKType = "a";
				case "Dis":rollAKType = "x";
				default : rollAKType = "s"
			]
		}]
		[h, if(!json.contains(tParse,"modifier")):modifier = "none"]
		[h, if(modifier=="Other"),CODE:{
			[h: input("Custom_Modifier")]
			[h, if(!isNumber(Custom_Modifier)): modifier = 1 ; modifier = if(Custom_Modifier==0,1,Custom_Modifier)]
		};{
			[h, switch(modifier):
				case "1/2": modifier = 0.5;
				case "1/4": modifier = 0.25;
				case "1 ¼": modifier = 1.25;
				case "1 ½": modifier = 1.5;
				case "2": modifier = 2;
				default: modifier = 1
			]
		}]
		[h: modifier = number(string(modifier))]
		[h: macHTML = ""]

		[h, if(hitDice!=""),CODE:{
			[h, macro("rollDie@this"):rollAKType+"1d20"+if(hitBonus>0,"+"+hitBonus,if(hitBonus<0,hitBonus,""))]
			[h: hitAttempt = json.get(macro.return,"rollData")]
			[h: hitAttemptDice = json.get(macro.return,"rolledDice")]
			[h: hitTotal = json.get(macro.return,"rolledTotal")]			
			[h: attackDiceThrown = json.get(macro.return,"diceThrown")]
			[h: hitCrit = if(hitAttempt==20,1,if(hitAttempt==1,-1,0))]
		};{
			[h: hitTotal = 0]
			[h: hitAttemptDice = ""]
			[h: hitCrit = 0]
			[h: tokenIDs = ""]
			[h: libDice = 0]
		}]
		[h: attackHTML = '<font style="font-size:16pt"><b>'+if(hitCrit==1,"<i>Critical Hit</i> Attack: ",if(hitCrit==-1,"<i>Failed</i> Attack: ","Attack: "))+if(opt_RML,hitTotal,'<span title="'+hitTotal+' attack">'+macroLink(hitTotal,"Process Macro@this","self",json.append("","ac",encode(hitJSON),attackerID))+'</span>')+'</b><font style="font-size:12pt"> r('+hitAttemptDice+if(hitBonus>0,",+"+hitBonus,if(hitBonus<0,","+hitBonus,""))+')<br>']
		[h: damageJSON = ""]
		[h: missedJSON = ""]
		[h: damageTotal = 0]
		[h: damageDice = ""]

		[h, foreach(oneToken,tokenIDs),CODE:{
			[h, if(hasProperty("AC",oneToken)): targetAC = getProperty("AC",oneToken) ; targetAC = 0]
			[h, if(opt_ATO==0 || hitCrit=-1 && (hitTotal>=targetAC || hitCrit==1)): damageJSON = json.append(damageJSON,oneToken) ; 
				missedJSON = json.append(missedJSON,oneToken)]
		}]


		[h, if(damageJSON!="" && opt_RDG==2),CODE:{
[h, if(macDebug): broadcast("Aa "+hitDamageSec)]
			[h: damageTotal = hitDamage+hitDamageSec]
			[h: damageDice = hitDamage+if(hitDamageSec>0,","+hitDamageSec,"")]
		}]




		[h, if(hitDice!="" && opt_RDG==0),CODE:{

[h, if(macDebug):broadcast(" A ")]			

			[h, macro("rollDie@this"):hitDice]
			[h: damageDiceThrown = json.get(macro.return,"diceThrown")]
			[h: damageTotal = json.get(macro.return,"rolledTotal")]
			[h: damageBonus = json.get(macro.return,"rollBonus")]
			[h: damageDice = replace(json.get(macro.return,"rolledDice"),'"','')]
			[h, if(damageBonus!=0): damageDice = listAppend(damageDice,if(damageBonus>0,"+"+damageBonus,damageBonus))]
			[h, if(hitDiceSec!=""),macro("rollDie@this"):hitDiceSec]
			[h, if(hitDiceSec!=""): damageSecDiceThrown = json.get(macro.return,"diceThrown"); damageSecDiceThrown = ""]
			[h, if(hitDiceSec!=""): damageSecTotal = json.get(macro.return,"rolledTotal")]
			[h, if(hitDiceSec!=""): damageSecBonus = json.get(macro.return,"rollBonus") ; damageSecBonus = 0]
			[h, if(!isNumber(damageSecBonus)): damageSecBonus = 0]
			[h, if(hitDiceSec!=""): damageSecDice = replace(json.get(macro.return,"rolledDice"),'"','')]
			[h, if(hitDiceSec!="" && damageSecBonus!=0): damageSecDice = listAppend(damageSecDice,if(damageSecBonus>0,"+"+damageSecBonus,damageSecBonus))]
			[h, if(hitDiceSec!=""): damageTotal = damageTotal + damageSecTotal]
			[h, if(hitDiceSec!=""): damageDice = listAppend(damageDice,damageSecDice)]
			[h, if(hitDiceSec!=""): damageDiceThrown = json.append(damageDiceThrown,damageSecDiceThrown)]
			[h, if(modifier!=1): damageTotal = round(damageTotal * modifier,0)]
		}]

		[h, if(opt_ATO!=0 && damageJSON!="" || missedJSON!="" ):macHTML = macHTML + "<hr>"]

		[h, if(hitDice!="" && damageJSON!="" && opt_RDG!=1),foreach(oneToken,damageJSON),CODE:{
[h, if(macDebug): broadcast("Ab " + damageTotal)]
			[h, macro("Hurt@this"):json.set("","oneToken",if(opt_ATO==2 && damageTotal>0,oneToken,""),"vDamage",damageTotal,"vSilent",1)]
			[h, if(macro.return==""): attackHTML = attackHTML + "<font style='font-size:16pt'>"+ if(opt_ATO!=0,"<b>Damage: " +if(opt_RML,damageTotal,'<span title="'+damageTotal+' damage">'+macroLink(damageTotal,"Process Macro@this","self",json.append("","hurt",damageTotal,attackerID))+'</span>')+"</b><font style='font-size:12pt'> r("+damageDice+")"+if(modifier!=1," + "+modifier+"x modifier!","")+"<br>","")+ "<font style='font-size:12pt'>"]

			[h, if(macro.return==""): macHTML = macHTML + getName(oneToken)+" was <b>Hit !</b>"; macHTML = macHTML + replace(macro.return,"took ",": <b>Damage: </b>")+if(modifier!=1," with "+modifier+"","")+"<br>"]

		}]

		[h, if(opt_ATO && missedJSON!=""),CODE:{
			[h, foreach(oneToken,missedJSON): macHTML = listAppend(macHTML,getName(oneToken)+" was NOT HIT by the attack!","")+"<br>"]
			[h: hitDice = ""]
		}]

		[h, if(hitDice!="" && opt_RDG==1 && damageJSON!=""),foreach(oneToken,damageJSON),CODE:{

[h, if(macDebug): broadcast(" B " + oneToken)]			

			[h, macro("rollDie@this"):hitDice]
			[h: damageDiceThrown = json.append(damageDiceThrown,json.get(macro.return,"diceThrown"))]
			[h: damageTotal = json.get(macro.return,"rolledTotal")]
			[h: damageBonus = json.get(macro.return,"rollBonus")]
			[h: damageDice = replace(json.get(macro.return,"rolledDice"),'"','')]
			[h, if(damageBonus!=0): damageDice = listAppend(damageDice,if(damageBonus>0,"+"+damageBonus,damageBonus))]
			[h, if(hitDiceSec!=""), macro("rollDie@this"):hitDiceSec]
			[h, if(hitDiceSec!=""): damageSecDiceThrown = json.append(damageSecDiceThrown,json.get(macro.return,"diceThrown")); damageSecDiceThrown = ""]
			[h, if(hitDiceSec!=""): damageSecTotal = json.get(macro.return,"rolledTotal")]
			[h, if(hitDiceSec!=""): damageSecBonus = json.get(macro.return,"rollBonus") ; damageSecBonus = 0]
			[h, if(!isNumber(damageSecBonus)): damageSecBonus = 0]
			[h, if(hitDiceSec!=""): damageSecDice = replace(json.get(macro.return,"rolledDice"),'"','')]
			[h, if(hitDiceSec!="" && damageSecBonus!=0): damageSecDice = listAppend(damageSecDice,if(damageSecBonus>0,"+"+damageSecBonus,damageSecBonus))]
			[h, if(hitDiceSec!=""): damageTotal = damageTotal + damageSecTotal]
			[h, if(hitDiceSec!=""): damageDice = listAppend(damageDice,damageSecDice)]
			[h, if(hitDiceSec!=""): damageDiceThrown = json.merge(damageDiceThrown,damageSecDiceThrown)]
			[h, if(modifier!=1): damageTotal = damageTotal * modifier]
[h, if(macDebug): broadcast(" Ba " + damageTotal)]
			[h, macro("Hurt@this"):json.set("","oneToken",if(opt_ATO==2,oneToken,""),"vDamage",damageTotal,"vSilent",1)]
			[h, if(macro.return!=""): macHTML = macHTML + replace(macro.return,"took ",": <b>Damage: ")+"</b>"+if(modifier!=1,"with "+modifier+"","")+" r("+damageDice+")<br>"]
			[h, if(macro.return=="" && opt_ATO!=0): macHTML = macHTML + getName(oneToken)+": <b>Damage: " +if(opt_RML,damageTotal,'<span title="'+damageTotal+' damage">'+macroLink(damageTotal,"Process Macro@this","self",json.append("","hurt",damageTotal))+'</span>')+ "</b>"+if(modifier!=1,"with "+modifier+"","")+" r("+damageDice+")<br>"]
[h, if(macDebug): broadcast(" Bb ")]
		}]


		[h, if(hitDice!="" && damageDiceThrown!=""): fullDiceThrown = json.merge("",attackDiceThrown,damageDiceThrown) ; fullDiceThrown = attackDiceThrown]

		[h: pOutput = replace(pOutput,"<b></b>",attackHTML)]
		[h: macHTML = replace(pOutput,"</div></div>",macHTML)+"</div></div>"]
		[h: processorLink = macroLinkText("Perform Macro@Lib:MonsterMaker", "none")]
		[h: outputButtons = '<form action="'+processorLink+'" method="json">
				<input type="hidden" name="pOutput" value="'+encode(macHTML)+'">
				<input type="hidden" name="cName" value="'+pName+'">
				<input type="submit" name="submit" value="Share">']
		[h: finalOutput = replace(macHTML,"</b>","</b>"+outputButtons,1)]


		[h, if(libDice==0),CODE:{

			[h, if(listFind(chatList,cName)>=0):chatList = listDelete(chatList,listFind(chatList,cName))]
			[h: broadcast(finalOutput,gmList)]
			[h: broadcast(pOutput,chatList)]
		}]

	};
	case "none":{};
	default: {
[h, if(macDebug): broadcast("DEFAULT " +submit)]
		}
]

[h, if(libDice==1 && length(fullDiceThrown)>5),CODE:{
	[h, if(isOverlayVisible("DiceOverlay_"+pName+"_Rolled")):closeOverlay("DiceOverlay_"+pName+"_Rolled")]
	[h, if(json.length(fullDiceThrown)>1),CODE:{
		[h, macro("rollDie@this"):json.set("","fullDiceThrown",fullDiceThrown)]
		[h: json.toVars(macro.return)]
	}]
}]

[h, if(libDice==1 && finalOutput!="" && fullDiceThrown!=""),CODE:{
	[h: fullDiceThrown = json.toList(fullDiceThrown)]

[h, if(macDebug): broadcast("full end   " +fullDiceThrown)]

	[h: tokDiceProp = json.set(tokDiceProp,"runAfter",json.set("","macro","Perform Macro@Lib:MonsterMaker","params",encode(finalOutput),"player",pName))]
	[h: setLibProperty("LibDiceOverlay",tokDiceProp,"lib:"+pName)]
	[h, if(findToken(attackerID)!=""): fullDiceThrown = fullDiceThrown+";sTokenID="+attackerID]
	[h, if(findToken(tokenIDs)!=""): fullDiceThrown = fullDiceThrown+";dTokenID="+tokenIDs ; fullDiceThrown = fullDiceThrown+if(findToken(attackerID)!="",";dTokenID="+attackerID,"")]
	[h: rollDO(fullDiceThrown)]
}]

