[h: this = getMacroLocation()]
[h: thisProp = "Lib"+listGet(this,1,":")]
[h: libJSON = getLibProperty(thisProp,this)]
[h: json.toVars(libJSON)]
[h: json.toVars(MMsettings)]

[h, if(0==1 || mmDebug),CODE:{
	[h: broadcast(getMacroName() +"<br>"+ obj)]
}]

[h: obj = replace(obj,'\\\\"',"")]

[h: name = json.get(obj,"name")]

[h: source = json.get(obj,"source")+", page "+json.get(obj,"page")]

[h, if(json.contains(obj,"trapHazType")): trapHazType = json.get(obj,"trapHazType") ; trapHazType = ""]
[h, switch(trapHazType):
	case "SMPL": type = "Simple trap";
	case "MECH": type = "Mechanical trap";
	case "MAG": type = "Magical trap";
	case "CMPX": type = "Complex trap";
	case "WLD": type = "Wilderness Hazard";
	case "WTH": type = "Weather";
	case "EST": type = "Eldritch Storm";
	case "ENV": type = "Environmental Hazard";
	case "GEN": type = "Generic";
	default: type = "Hazard"
]


[h, if(json.contains(obj,"rating")),CODE:{
	[h: ac = ""]
	[h: tier = 0]
	[h: threat = ""]
	[h: json.toVars(json.get(json.get(obj,"rating"),0))]
};{
	[h: ac = ""]
	[h: threat = ""]
	[h: tier = 0]
}]


[h, if(tier): acText = "<b>Trap Tier:</b> "+if(tier!=0,tier,"") ; acText = ""]
[h, if(threat!=""): acText = acText+"; <b>"+upper(threat,1)+"</b>"]

[h: size = ""]
[h, if(json.contains(obj,"initiative")): acText = acText + "<br><b>Trap Initiative:</b> "+json.toList(json.get(obj,"initiative"))]
[h, if(json.contains(obj,"duration")),CODE:{
	[h: tVar = json.get(obj,"duration")]
	[h, if(json.type(tVar)=="ARRAY"),CODE:{
		[h: tVar = json.get(tVar,0)]
		[h, if(json.contains(tVar,"type")): text = json.get(tVar,"type") ; text = ""]
		[h, if(json.contains(tVar,"condition")): text = text +", " +json.get(tVar,"condition")]
	};{
		[h: text = tVar]
	}]
	[h: acText = acText + "<br><b>Duration:</b> "+ upper(text,1)]
}]

