[h: newJSON = ""]
[h: text = ""]

[h, if(indexOf(entryJSON,"<b>")<0),CODE:{
	[h: newJSON = json.set("",tName,json.set("","entry",json.toList(entryJSON,"<br>")))]
	[h: entryJSON = ""]
}]
[h, while(!json.isEmpty(entryJSON)),CODE:{
	[h: entry = json.get(entryJSON,0)]
	[h: entryJSON = json.remove(entryJSON,0)]
	[h, if(startsWith(entry,"<b>") && endsWith(entry,"</b>")),CODE:{
		[h: name = substring(entry,0,length(entry))]
		[h: entry = json.toList(json.get(entryJSON,0))]
		[h: entryJSON = json.remove(entryJSON,0)]
		[h: newJSON = json.set(newJSON,name,json.set("","entry",entry))]
	};{
		[h: text = text + if(text!="","<br>","")+json.toList(entry,"<br>")]
	}]
}]


[h, if(text!=""),CODE:{
	[h: tJSON = json.set("",tName,json.set("","entry",text))]
	[h: newJSON = json.merge(tJSON,newJSON)]
}]


