}]
[h: fJSON = ""]
[h: text = ""]

[h, foreach(oneObj,objJSON),CODE:{


[h: 'broadcast("pO " +json.type(oneObj)+"^"+ oneObj) ']	

	[h, if(json.contains(oneObj,"mode")),CODE:{
		[macro("parseObject@"+this):json.append("",oneObj,"items")]
		[h: fJSON = json.append(fJSON,macro.return)]
	}]
[h: 'broadcast(roll.count+": "+" "+json.type(oneObj)+": "+json.fields(oneObj)+"<br>"+oneObj)']

	[h, if(json.contains(oneObj,"type")): type = json.get(oneObj,"type") ; type = ""]
	[h, if(json.contains(oneObj,"items")): items = json.get(oneObj,"items") ; items = ""]
	[h, if(json.contains(oneObj,"name")): name = json.get(oneObj,"name") ; name = ""]
	[h, if(json.contains(oneObj,"entry")): entry = json.get(oneObj,"entry") ; entry = ""]
	[h, if(json.contains(oneObj,"entries")): entries = json.get(oneObj,"entries") ; entries = ""]

[h, if(type == "inset"),CODE:{
		[macro("parseObject@"+this):json.append("",oneObj,"entries")]
		[h, if(name!=""): fJSON = json.append(fJSON,"<b>"+name+"</b>",json.toList(macro.return,"<br>")) ; fJSON = json.append(fJSON,"<br>"+json.toList(macro.return,"<br>"))]

}]
	[h, if(items=="" && type=="entries"),CODE:{
		[macro("parseObject@"+this):json.append("",oneObj,"entries")]

		[h, if(name!=""): fJSON = json.append(fJSON,"<b>"+name+"</b>")]
		[h: fJSON = json.append(fJSON,macro.return)]

[h: '		[h: fJSON = json.append(fJSON,json.toList(macro.return,"<br>")) ']

	}]
	[h, if(items=="" && type=="table"),CODE:{
		[h, if(name!=""): fJSON = json.append(fJSON,"<b>"+name+"</b>")]
		[macro("parseTable@"+this):json.append("",oneObj)]
		[h, if(!json.isEmpty(macro.return)):  fJSON = json.append(fJSON,macro.return)]
	}]

	[h, if(json.type(oneObj)=="UNKNOWN"),CODE:{
		[h, if(name!=""): fJSON = json.append(fJSON,json.set("",name,json.set("","entry",json.toList(oneObj,"<br>")))) ; fJSON = json.append(fJSON,json.toList(oneObj,"<br>"))]
	}]


	[h, if(items!=""),CODE:{
		[h: tType = json.get(items,0)]
		[h, if(json.contains(tType,"type")):tType = json.get(tType,"type") ; tType = ""]
	};{
		[h: tType = ""]
	}]	
	[h, if(items!="" && tType == "item" ),CODE:{
		[macro("parseJSON@"+this):json.append("",oneObj,"items")]

		[h, if(name!=""): fJSON = json.append(fJSON,json.set("",name,json.set("","entry",json.toList(macro.return,"<br>"))))  ; fJSON = json.append(fJSON,macro.return)]

	}]
	[h, if(items!="" && tType=="" && type=="list" ),CODE:{
		[h, if(name!=""): fJSON = json.append(fJSON,"<b>"+name+"</b>")]
		[h: fJSON = json.append(fJSON,items)]
	}]
}]
