[h: eJSON = json.path.read(parseJSON,"['entries']")]
[h: pNames = json.path.read(eJSON,".name")]
[h: pEntries = json.path.read(eJSON,".entries")]

[h: newJSON = ""]


[h, if(json.isEmpty(pNames)),CODE:{
	[h: newJSON = json.set("","Object Notes",json.set("","entry",json.toList(json.get(eJSON,0),"<br")))]
	[h: eJSON = ""]
}]
[h: aLoop = 0]
[h, foreach(oneEntry,eJSON),CODE:{

	[h, if(indexOf(oneEntry,'"name"')<0),CODE:{
		[h: tNames = ""]
		[h: sNames = ""]
		[h: tEntries = ""]
		[h: sEntries = ""]
	};{
		[h: tNames = json.path.read(oneEntry,".name")]
		[h: tEntries = json.path.read(oneEntry,".entries")]
		[h: tEntry = json.get(tEntries,0)]
		[h: sNames = json.path.read(tEntry,".name")]
		[h: sEntries = json.path.read(tEntry,".entries")]
	}]
	[h: sLoop = 0]
	[h, foreach(oneItem,sEntries),CODE:{
		[if(indexOf(oneItem,'"table"')>=0), macro("parseTable@this"):json.append("",oneItem) ; macro.return = oneItem]
		[h: sEntries = json.set(sEntries,sLoop,macro.return)]
		[h: sLoop = sLoop + 1]
	}]	
	[h: sLoop = 0]
	[h: sJSON = ""]
	[h, foreach(oneName,sNames),CODE:{

		[h: sJSON = json.set(sJSON,oneName,json.get(sEntries,sLoop))]
		[h: sLoop = sLoop + 1]
	}]
	[h, if(sLoop>0),CODE:{
		[h: tNames = json.difference(tNames,sNames)]
[h:' fEntry = json.set(sJSON,"entry",json.toList(json.get(json.get(tEntries,0),0),"<br>")) ']
		[h: fEntry = json.set(sJSON,"entry",json.toList(json.get(json.get(tEntries,0),0),"<br>"))]
	};{
		[h, if(tNames==""): newJSON = json.set(newJSON,"Object Info",json.set("","entry",oneEntry)) ;  fEntry = json.set("","entry",json.toList(json.get(tEntries,sLoop),"<br>"))]
	}]
	[h: sLoop = 0]
	[h, foreach(oneName,tNames),CODE:{
		[h, if(indexOf(sNames,oneName)<0): newJSON = json.set(newJSON,json.get(tNames,sLoop),fEntry)]

		[h: sLoop = sLoop + 1]
	}]

[h: aLoop = aLoop + 1]

}]

[h: macro.return = newJSON]

[h: this = getMacroLocation()]

[h: inputJSON = json.get(macro.args,0)]
[h: targetGRP = json.get(macro.args,1)]
[h, if(argCount()>2): chkFW = json.get(macro.args,2); chkFW = "RT"]

[h: targetJSON = json.get(inputJSON,targetGRP)]


[h, if(0==1 ),CODE:{
	[h: broadcast(getMacroName() +"<br>"+ targetJSON)]
}]

[h: repeat = json.fields(targetJSON)]

[h: outputDATA = ""]
[h: sLoopA = 0]
[h,count(listcount(repeat)),code:{

	[h: targetObj = json.get(targetJSON,sLoopA)]

	[h: items = ""]	
	[h: item = ""]
	[h, if(json.contains(targetObj,"entries")): entry = json.get(targetObj,"entries") ; entry = ""]
	[h, if(json.contains(targetObj,"entry")): entry = json.get(targetObj,"entry")]
	[h, if(json.contains(targetObj,"type")): type = json.get(targetObj,"type") ; type = ""]
	[h, if(json.contains(targetObj,"items")): items = json.get(targetObj,"items") ; items = ""]
	[h, if(json.contains(targetObj,"name")): name = json.get(targetObj,"name") ; name = ""]
	[h, if(indexOf(name,"{@")>=0 && indexOf(name,"{@recharge")<0),CODE:{
		[h, macro("ProcessAts@this"):json.append("",name,"s","nolink")]
		[h: name = macro.return]
	}]
	[h, if(indexOf(entry,'"items"')>=0),CODE:{
		[macro("parseEntry@"+this):json.get(targetObj,"entries")]
		[h, if(json.contains(macro.return,"text")):entry = json.get(macro.return,"text") ; entry = ""]
		[h, if(json.contains(macro.return,"items")):itemJSON = json.get(macro.return,"items") ; itemJSON = ""]
	};{
		[h: itemJSON = ""]
	}]

	[h, if(items=="" && type=="table"),CODE:{
		[macro("parseTable@"+this):json.append("",targetObj)]
		[h: items = json.append(fJSON,macro.return)]
		[h: entry = ""]

	}]
	[h: tTable = ""]
	[h, foreach(oneEntry,entry),if(json.contains(oneEntry,"caption")),CODE:{
		[macro("parseTable@"+this):json.append("",oneEntry)]
		[tTable = macro.return]
	}]
	[h,count(json.length(itemJSON)),CODE:{
		[h: itemObj = json.get(itemJSON,roll.count)]

		[h, if(json.contains(itemObj,"name")): itemName = json.get(itemObj,"name")]
		[h, if(json.contains(itemObj,"entry")): item = json.get(itemObj,"entry")]
		[h, if(json.contains(itemObj,"entries")): item = json.get(itemObj,"entries")]
		[h: items = json.set(items,itemName,item)]
	}]

	[h, if(entry!=""): items = json.set(items,"entry",json.get(entry,0)+if(tTable!="","<br>"+tTable,""))]


	[h, if(json.length(targetObj)==1 && name=="" && entry=="" && items==""): entry = targetObj]

	[h, if(name=="" && entry==targetObj), CODE:{
		[h: outputDATA = json.append(outputData,if(json.type(entry)=="UNKNOWN",json.toList(entry),entry))]
	};{
		[if(name==""): outputDATA = json.append(outputData,json.get(entry,0)) ; outputDATA = json.set(outputData,name,if(items=="",json.get(entry,0),items))]
	}]
	[h: sLoopA = sLoopA + 1]
}]

[h: macro.return=outputDATA]

