[r, overlay("MM_Show Image", "width="+(imgW)+"; height="+(imgH)+"; temporary = 1; input = 0; noframe = 0"): {{formHTML}}]

[h: 'broadcast(getMacroName()+" - "+macro.args)']
[h, if(argCount()!=2): return(0,"")]
[h: scrubMode = json.get(macro.args,0)]
[h: scrubString = decode(json.get(macro.args,1))]

[h, while(indexOf(scrubString,"<a href='macro://")>0),CODE:{
	[h: bVar = indexOf(scrubString,"<a href='macro://")]
	[h: mVar = indexOf(scrubString,"'>",bVar)+2]
	[h: eVar = indexOf(scrubString,"</a>",mVar)]
	[h: mText = substring(scrubString,mVar,eVar)]
	[h: scrubString = substring(scrubString,0,bVar) + mText + substring(scrubString,eVar+4)]
}]
[h, if(listFind(scrubMode,"noShare")>=0 && indexOf(scrubString,'<input type="submit" name="submit" value="Share">')>0),CODE:{
	[h: bVar = indexOf(scrubString,'<input type="submit" name="submit" value="Share">')]
	[h: eVar = indexOf(scrubString,'">',bVar)+2]
	[h: scrubString = substring(scrubString,0,bVar)+substring(scrubString,eVar)]
}]
[h, if(listFind(scrubMode,"noOption")>=0 && indexOf(scrubString,'<select')>0),CODE:{	
	[h, while(indexOf(scrubString,'<select')>0),CODE:{
		[h: bVar = indexOf(scrubString,'<select')]
		[h: eVar = indexOf(scrubString,'</select>',bVar)+9]
		[h: scrubString = substring(scrubString,0,bVar) + substring(scrubString,eVar)]
	}]
}]
[h, if(listFind(scrubMode,"full")>=0),CODE:{
	[h, while(indexOf(scrubString,'<input type="submit"')>0),CODE:{
		[h: bVar = indexOf(scrubString,'<input type="submit"')]
		[h: eVar = indexOf(scrubString,'">',bVar)+2]
		[h: scrubString = substring(scrubString,0,bVar) + substring(scrubString,eVar)]
	}]
	[h, while(indexOf(scrubString,'<select')>0),CODE:{
		[h: bVar = indexOf(scrubString,'<select')]
		[h: eVar = indexOf(scrubString,'</select>',bVar)+9]
		[h: scrubString = substring(scrubString,0,bVar) + substring(scrubString,eVar)]
	}]
}]
[h, while(listFind(scrubMode,"full")>=0 && indexOf(scrubString,"HP: ")>0 && indexOf(scrubString," : <b>Damage")>0),CODE:{
	[h: bVar = indexOf(scrubString,"HP: ")]
	[h: eVar = indexOf(scrubString," : <b>Damage",bVar)]
	[h, if(bVar>0 && eVar>0 && bVar<eVar),CODE:{
		[h: scrubString = substring(scrubString,0,bVar)+"HP!  "+substring(scrubString,eVar+3)]
	}]
}]

[h: macro.return=encode(scrubString)]

[h: tName = listGet(macro.args,0,"^")]
[h: type = listGet(macro.args,1,"^")]

[h,if(json.type(type)=="OBJECT"),code:{
	[creatureTag = ""]
	[creaturePre = ""]
	[h: creatureType = upper(json.get(type,"type"),1)]
	[h: creatureTags = json.get(type,"tags")]
	[h, if(json.type(creatureTags)=="ARRAY"),code:{
		[h: creatureTags = json.get(creatureTags,0)]
		[h, if(json.contains(creatureTags,"tag")): creatureTag = upper(json.get(creatureTags,"tag"),1)]
		[h, if(json.contains(creatureTags,"prefix")): creaturePre = upper(json.get(creatureTags,"prefix"),1)+" "]
	}]
	[h, if(json.contains(type,"swarmSize")): swarmSize = json.get(type,"swarmSize") ; swarmSize = ""]
	[h, switch(swarmSize):
		case "T": swarmSize = "swarm of Tiny ";
		case "S": swarmSize = "swarm of Small ";
		case "M": swarmSize = "swarm of Medium ";
		case "L": swarmSize = "swarm of Large ";
		case "G": swarmSize = "swarm of Giant ";
		default: ""
	]
	[h, if(swarmSize!=""): creatureType = swarmSize + creatureType+if(endsWith(tName,"s"),"s","")]

	[h, if(indexOf(type,'"choose"')>0),CODE:{
		[h: type = capitalize(type)]
		[h: creatureType = json.toList(json.get(json.path.read(type,".Choose"),0)," or ")]
	}]

	[h: type = creatureType+if(creatureTag=="",if(creatureTags=="",""," ("+upper(creatureTags,1)+")")," ("+creaturePre+creatureTag+")")]
}]
[h: macro.return=type]

[h: tokenRef = getMacroLocation()]
[h, if(startsWith(tokenRef,"Token:")),CODE:{
	[h: tokenRef = findToken(getSelected())]
	[h, if(listCount(tokenRef)>1 || tokenRef==""):return(0)]
}]
[h: tMacro=getMacroButtonIndex()]
[h: tGroup=json.get(getMacroProps(tMacro,"json",tokenRef),"group")]
[h: tMacroIDs=getMacroGroup(tGroup,",",tokenRef)]
[h: vThisMacro = getMacroName()]
[h: vExpandedLabel  = "Collapse "+tGroup]
[h: vCollapsedLabel = "Expand "+tGroup]
[h: vMacID = getMacroButtonIndex()]
[h: vThisMacroProps = getMacroProps(getMacroButtonIndex(),",",tokenRef)]
[h, if(matches(vThisMacro, vExpandedLabel) || matches(vThisMacro, "Collapse")), code: {
	[h: setMacroProps(getMacroButtonIndex(), json.set("{}", "label", vCollapsedLabel), "json",tokenRef)]
	[h: expand = 1]
};{
	[h: setMacroProps(getMacroButtonIndex(), json.set("{}", "label", vExpandedLabel), "json",tokenRef)]
	[h: expand = 0]
}]
[h, foreach(tMacro,tMacroIDs), CODE:{
	[h: macJSON = getMacroProps(tMacro,"json",tokenRef)]
	[h: maxWidth = ""]
	[h: json.toVars(macJSON)]
	[h, if(sortBy == ""):sortBy = 1]
	[h, if(expand),CODE:{
		[h: 'grow stuff']
		[h: json.toVars(maxWidth)]
		[h: macJSON = ""]
		[h: setMacroProps(tMacro, json.set("{}", "maxWidth", macJSON,"fontSize", fsize,"minWidth", width,"sortBy",sortBy), "json",tokenRef)]
	};{
		[h: 'shrink stuff']
		[h: macJSON = json.set("","width",minWidth,"fsize",fontSize)]
		[h: setMacroProps(tMacro, json.set("{}", "maxWidth", macJSON), "json",tokenRef)]
		[h: minWidth = "0"]
		[h: fontSize = "0.0em"]
		[h, if(tMacro != vMacID): setMacroProps(tMacro, json.set("{}", "fontSize", fontSize,"minWidth", minWidth,"sortBy",sortBy), "json",tokenRef)]
	}]
}]

[h: macDebug = 0]
[h, if(macDebug):broadcast(getMacroName()+"^"+json.length(macro.args)+"^"+macro.args,"self")]

[h: this = getMacroLocation()]
[h: thisProp = replace(this,":","")]
[h: libJSON = getLibProperty(thisProp,this)]
[h: json.toVars(json.get(libJSON,"MMsettings"))]
[h, if(lower(chatList)=="all" && lower(gmList)=="gm"),CODE:{
	[h: gmList = ""]
	[h: chatList = ""]
	[h, foreach(oneP, getAllPlayerNames()), if(isGM(oneP)): gmList = listAppend(gmList,oneP) ; chatList = listAppend(chatList,oneP)]
}]
[h: pName = getPlayerName()]

[h, if(isFunctionDefined("rollDO")): tokDiceProp = getLibProperty("LibDiceOverlay","lib:"+pName) ; tokDiceProp = ""]
[h, if(json.contains(tokDiceProp,"runAfter")),CODE:{
	[h: runAfter = json.get(tokDiceProp,"runAfter")]
	[h: tokDiceProp = json.remove(tokDiceProp,"runAfter")]
	[h: setLibProperty("LibDiceOverlay",tokDiceProp,"lib:"+pName)]
	[h, if(json.contains(runAfter,"player")): cName = json.get(runAfter,"player") ; cName = ""]
	[h: finalOutput = json.get(runAfter,"params")]
	[h, if(cName == pName),CODE:{
		[h, macro("scrubLinks@this"):json.append("noShare",finalOutput)]
		[h: sOutput = decode(macro.return)]
		[h, if(listFind(chatList,cName)>=0):chatList = listDelete(chatList,listFind(chatList,cName))]
	};{
		[h: sOutput = ""]
	}]
	[h, macro("scrubLinks@this"):json.append("full",finalOutput)]
	[h: pOutput = decode(macro.return)]
	[h: finalOutput = decode(finalOutput)]
	[h, if(opt_DCE && opt_COO && finalOutput!=""),CODE:{
		[h, if(opt_COO==2 && chatList!="" && chatList!=gmList): broadcast(pOutput,chatList)]
		[h, if(opt_COO!=2 && cName!="" && sOutput!=""): broadcast(sOutput,cName)]
		[h, if(opt_COO==2): broadcast(pOutput,chatList)]
		[h: execFunction("broadcast",json.append("",finalOutput,"self"),1,gmList)]
		[h: return(0,"")]
	};{
		[h: libDice = 0]
	}]
};{
	[h, if(tokDiceProp!="" && opt_DCE!=0): libDice = 1 ; libDice = 0]
}]

[h, if(argCount()<3):return(0,"") ; tParse = macro.args]


[h: macType = json.get(tParse,0)]
[h: macData = json.get(tParse,1)]
[h: tokenID = json.get(tParse,2)]
[h: tokenIDs = getSelected("json")]
[h: sTokenID = tokenID]
[h: dTokenID = tokenIDs]

[h, if(findToken(tokenID)==""):return(0,"")]
[h: tokenImp = getImpersonated(1)]

[h, if(isGM() && tokenImp!="" && tokenID != tokenImp),CODE:{
	[h, if(findToken(tokenImp)!=""): IamGM = if(getGMName(tokenImp)=="DM",1,0) ; IamGM = 0]
};{
	[h: tokOwners = getOwners("json",tokenID)]
	[h: IamGM = if(isGM() || json.indexOf(tokOwners,pName)>=0,1,0)]
	[h, if(1==0 && IamGM && indexOf(gmList,pName)<0): gmList = listAppend(gmList,pName)]
}]

[h, if(!IamGM):return(0)]


[h, if(findToken(tokenID)==""):return(0,"") ; tokJSON = getProperty(thisProp,tokenID)]
[h: macName = ""]
[h: macHTML = ""]
[h: macDetail = ""]
[h: hitJSON = ""]
[h: damageJSON = ""]
[h: customButtons = ""]
[h: fullDiceThrown = ""]

[h, if(argCount()==4): usedSS = 0 ; usedSS = 1]

[h: allStates = json.path.read(getInfo("campaign"), ".states..name")]
[h: libTokens = json.path.read(getInfo("client"),"['library tokens']")]

[h, if(json.contains(allStates,"Advantage") && json.contains(allStates,"Disadvantage")),CODE:{
	[h, if(getState("Advantage",tokenID)):rollType = "Adv"]
	[h, if(getState("Disadvantage",tokenID)):rollType = "Dis"]
};{
	[h: rollType = "Std"]
}]

[h: hitTypes = "acid,bludgeoning,cold,fire,force,lightning,necrotic,piercing,poison,psychic,radiant,slashing,thunder"]

[h, if(macType == "condition"): macType = "state"]

[h, if(macDebug): broadcast(macType)]

[h, if(indexOf(tParse,"{@atk")>=0 && macType!="Action"),CODE:{
	[h: macTypeSub = macType]
	[h: macType = "Action"]
};{
	[h: macTypeSub = ""]
}]
[h, if(mmDebug): broadcast(macType)]
[h, switch(macType),CODE:
	case "roll":{
		[h: usedSS = 1]
		[h: dTokenID = ""]
		[h, if(startsWith(macData,"c")),CODE:{
			[h: rollChance = listGet(macData,1)]
			[h: macData = substring(listGet(macData,0),1)]
		};{
			[h: rollChance = -1]
		}]
		[h, if(json.length(tParse)>=4): selfOnly = json.get(tParse,3) ; selfOnly = ""]
		[h, if(selfOnly=="self"):tokenIDs = tokenID]
		[h, if(!isGM() && IamGM): tokenIDs = tokenID]
		[h: macType = "Roll"]
		[h: chkSuccessIDs = ""]
		[h: chkFailIDs = ""]
		[h, if(indexOf(macData,"H")>=0 || indexOf(macData,"H")>=0),CODE:{
			[h, if(findToken(tokenID)==""):return(0)]
			[h: vStatus = input("vHP|0|Set HP|TEXT")]
			[h: abort(vStatus)]
			[h, if(!isNumber(vHP)):return(0,"")]
			[h: setProperty("HP",vHP,tokenID)]
			[h: setProperty("MaxHP",vHP,tokenID)]
			[h: tokJSON = json.path.set(tokJSON,".mmJSON..hp",vHP)]
			[h: tokJSON = json.path.set(tokJSON,".mmJSON..hd","")]
			[h: setProperty(thisProp,tokJSON,tokenID)]
			[h: return(0,"")]
		}]
		[h, foreach(oneToken,tokenIDs),CODE:{
			[h, if(roll.count>0):macHTML = macHTML + '<br>']
			[h, macro("rollDie@this"):macData]
			[h: json.toVars(macro.return)]
			[h, if(json.length(tokenIDs)>1): fullDiceThrown = json.append(fullDiceThrown,diceThrown) ; fullDiceThrown = diceThrown]
			[h, if(rollChance>=0):  finalText = if(rolledTotal<rollChance,'<font style="color: red;"> <b> !! FAIL !! </b>','<font style="color: green;"> <b> !! SUCCESS !! </b>') ; finalText = ""]
			[h, if(indexOf(finalText,"color: red;")>=0): chkFailIDs = listAppend(chkFailIDs,oneToken)]
			[h, if(indexOf(finalText,"color: green;")>=0): chkSuccessIDs = listAppend(chkSuccessIDs,oneToken)]
			[h, if(finalText != ""): macHTML = macHTML + strformat('<tr center><td>'+getName(oneToken)+'</td><td>'+macData+'</td><td>'+rolledDice+'</td><td>'+rolledTotal+' vs '+rollChance+'</td><td>'+finalText+'</td></tr>') ; macHTML = macHTML + strformat('<tr center><td>'+getName(oneToken)+'</td><td>'+rollType+' '+macData+'</td><td>'+rollHTML+if(rollBonus>0," +","")+if(rollBonus!=0,rollBonus,"")+'</td><td>'+rolledTotal+'</td></tr>')]
		}]
		[h, if(rollChance>=0),CODE:{
			[h: macHTML = '<table><tr><th>Name</th><th>Roll</th><th>Rolled</th><th>Result</th><th>Final</th></tr>'+macHTML+'</table>']
			[h: customButtons = '<input type="submit" name="submit" value="Select Fail"><input type="hidden" name="chkFailIDs" value="'+chkFailIDs+'"><input type="submit" name="submit" value="Select Success"><input type="hidden" name="chkSuccessIDs" value="'+chkSuccessIDs+'">']
		};{
			[h: macHTML = '<table><tr><th>Name</th><th>Roll</th><th>Rolled</th><th>Result</th></tr>'+macHTML+'</table>']
		}]
	};
	case "rollHurt":{
		[h: usedSS = 1]
		[h: dTokenID = ""]
		[h, if(json.isEmpty(tokenIDs) || !isGM()):return(0,"")]
		[h: macType = "Action"]
		[h, macro("rollDie@this"):macData]
		[h: json.toVars(macro.return)]
		[h: fullDiceThrown = diceThrown]
		[h: tokenNames = ""]
		[h, foreach(oneToken,tokenIDs),CODE:{
			[h, macro("Hurt@this"):json.set("","oneToken",if(!opt_ATO,"",oneToken),"vDamage",rolledTotal,"vSilent",1)]			
			[h: macHTML = listAppend(macHTML,macro.return,"<br>")]
		}]
		[h, if(!endsWith(rollBonus,"%")): rollBonus = if(rollBonus>0," +","")+if(rollBonus!=0,rollBonus,"")]
		[h: macHTML =strformat('<table><tr><th>Roll</th><th>Rolled</th><th>Bonus</th><th>Total</th></tr><tr center><td>'+macData+'</td><td>'+rolledDice+'</td><td>'+rollBonus+'</td><td>'+rolledTotal+'</td></tr></table><hr>'+macHTML)]

	};
	case "state":{
		[h: usedSS = 1]
		[h: libDice = 0]
		[h, if(json.isEmpty(tokenIDs) || !isGM()):return(0,"")]
		[h: condition = substring(lower(trim(macData)),0,5)]
		[h: macType = "State"]
		[h: selectedState = ""]
		[h, switch(condition):
			case "charm": selectedState = "Charmed";
			case "conce": selectedState = "Concentrating";
			case "deafe": selectedState = "Deafened";
			case "frigh": selectedState = "Frightened";
			case "grapp": selectedState = "Grappled";
			case "incap": selectedState = "Incapacitated";
			case "invis": selectedState = "Invisible";
			case "paral": selectedState = "Paralyzed";
			case "petri": selectedState = "Petrified";
			case "poiso": selectedState = "Poisoned";
			case "prone": selectedState = "Prone";
			case "restr": selectedState = "Restrained";
			case "stunn": selectedState = "Stunned";
			case "uncon": selectedState = "Unconscious";
			case "advan": selectedState = "Advantage";
			case "disad": selectedState = "Disadvantage";
			default: macType = ""
		]
		[h: macHTML = ""]
		[h, if(selectedState!="" && json.indexOf(allStates,selectedState)>=0), foreach(oneToken,tokenIDs),CODE:{
			[h: currentState = getState(selectedState,oneToken)]
			[h: macHTML = macHTML + getName(oneToken) +" has "+selectedState+if(currentState," removed."," set!.")+"<br>"]
			[h: setState(selectedState,if(currentState,0,1),oneToken)]
			[h, if(condition=="advan"): setState("Disadvantage",0,oneToken)]
			[h, if(condition=="disad"): setState("Advantage",0,oneToken)]
			[h, if(selectedState=="Invisible"):setOwnerOnlyVisible(if(getState("Invisible",oneToken),1,0),oneToken)]
		};{
			[h: macHtml = upper(macData,1) +" state was not found!"]	
		}]

	};
	case "castSpell":{
		[h: libDice = 0]
		[h: spellName = substring(macData,6)]
		[h, if(json.contains(libTokens,"Lib:SpellLibrary") && macHTML == ""),CODE:{
			[h, macro("Show-a-Spell@Lib:SpellLibrary"):spellName]
			[h: return(0,"")]
		};{
			[h, if(macHTML == ""):macHTML = "Lib:SpellLibrary was not found!"]
		}]
	};
	case "hurt":{
		[h: usedSS = 1]
		[h: libDice = 0]
		[h, if(json.isEmpty(tokenIDs) || !isGM()):return(0,"")]
		[h: macType = "Action"]
		[h, foreach(oneToken,tokenIDs),CODE:{
			[h, macro("Hurt@this"):json.set("","oneToken",if(!opt_ATO,"",oneToken),"vDamage",macData,"vSilent",0)]
			[h: macHTML = listAppend(macHTML,macro.return,"<br>")]
		}]
		[h: return(0,"")]
	};
	case "ac":{
		[h: usedSS = 1]		
		[h: libDice = 0]
		[h, if(json.isEmpty(tokenIDs)):return(0,"")]
		[h: macType = "Action"]
		[h: hitJSON = decode(macData)]
		[h: json.toVars(hitJSON)]
		[h: tokenID = attackerID]
		[h: damageJSON = ""]
		[h: missedJSON = ""]

		[h, if(!isGM() && IamGM): tokenIDs = tokenID]

		[h, foreach(oneToken,tokenIDs),CODE:{
			[h, if(hasProperty("AC",oneToken)): targetAC = getProperty("AC",oneToken) ; targetAC = 0]
			[h, if(hitTotal>=targetAC): damageJSON = json.append(damageJSON,oneToken) ; missedJSON = json.append(missedJSON,oneToken)]
		}]
		[h, if(missedJSON!=""),CODE:{
			[h, foreach(oneToken,missedJSON): macHTML = listAppend(macHTML,getName(oneToken)+" was NOT HIT by the attack!","")+"<br>"]
		}]
		[h, if(damageJSON!=""),CODE:{
			[h, foreach(oneToken,damageJSON): macHTML = listAppend(macHTML,getName(oneToken)+" was HIT by the attack!","")+"<br>"]
		}]
	};
	case "dc":{
		[h: usedSS = 1]
		[h: dTokenID = ""]
		[h, if(json.isEmpty(tokenIDs)):return(0,"")]
		[h, if(startsWith(macData,"spell")),CODE:{
			[h: rollDCType = substring(listGet(macData,1),0,1)]
			[h: rollDC = number(substring(listGet(macData,1),1))]
			[h: rollStat = "Generic"]
		};{
			[h: rollDCType = substring(listGet(macData,0),0,1)]
			[h: rollDC = number(substring(listGet(macData,0),1))]
			[h: rollStat = listGet(macData,1)]
			[h, if(rollStat==""):rollStat = "Generic"]
		}]
		[h: macType = "Legendary"]
		[h: macHTML = '<table><tr><th>Name</th><th>Roll</th><th>Rolled</th><th>Result</th><th>Final</th></tr>']
		[h: propName = upper(substring(rollStat,0,3),1)+"Mod"]

		[h: chkSuccessIDs = ""]
		[h: chkFailIDs = ""]
		[h: fullDiceThrown = ""]
		[h, if(!isGM() && IamGM): tokenIDs = tokenID]
		[h, foreach(oneToken,tokenIDs),CODE:{
			[h: tTokJSON = getProperty(thisProp,oneToken)]
			[h, if(json.contains(tTokJSON,"mmJSON")): tProp = json.path.read(tTokJSON,"mmJSON..save.."+lower(substring(rollStat,0,3))) ; tProp = ""]
			[h, if(!json.isEmpty(tProp)):tProp = json.get(tProp,0) ; tProp = ""]

			[h, if(hasProperty(propName,oneToken)): mod = if(tProp!="",tProp,getProperty(propName,oneToken)) ; mod = if(tProp!="",tProp,0)]
			[h, if(json.contains(allStates,"Advantage") && json.contains(allStates,"Disadvantage")): rollDCType = if(getState("Advantage",oneToken),"a",if(getState("Disadvantage",oneToken),"x","s"))]
			[h, macro("rollDie@this"):rollDCType+"1d20"+if(mod>0,"+"+mod,if(mod<0,mod,""))]
			[h: json.toVars(macro.return)]
			[h, if(json.length(tokenIDs)>1):fullDiceThrown = json.append(fullDiceThrown,diceThrown+";color=Plastic Orange") ; fullDiceThrown = diceThrown+";color=Plastic Orange"]
			[h, if(rolledTotal<rollDC):dcFailed = 1 ; dcFailed = 0]
			[h, if(dcFailed): chkFailIDs = listAppend(chkFailIDs,oneToken) ; chkSuccessIDs = listAppend(chkSuccessIDs,oneToken)]
			[h: macHTML = macHTML + strformat('<tr center>
			<td>'+getName(oneToken)+'</td>
			<td>'+rollType+' '+if(rollDCtype=="s",1,2)+'d20'+if(rollBonus>0," +","")+if(rollBonus!=0,rollBonus,"")+'</td>
			<td>'+rolledDice+'</td>
			<td>'+rolledTotal+'</td>
			<td>'+if(dcFailed,'<font style="color: red;"> <b> !! FAILED !! </b></td></tr>','<font style="color: green;"> <b> !! SUCCESS !! </b></td></tr>'))]

		}]
		[h: macHTML = macHTML + "</table>"]
		[h: macName = ' DC '+rollDC+' '+rollStat+' Check']
		[h: customButtons = strformat('<input type="submit" name="submit" value="Select Fail"><input type="hidden" name="chkFailIDs" value="'+chkFailIDs+'"><input type="submit" name="submit" value="Select Success"><input type="hidden" name="chkSuccessIDs" value="'+chkSuccessIDs+'">')]
	};
	case "skill":{
		[h: usedSS = 1]
		[h: dTokenID = tokenID]
		[h, if(json.contains(allStates,"Advantage") && json.contains(allStates,"Disadvantage")):rollTypeChk = 1 ; rollTypeChk = 0]
		[h, if(findToken(tokenID)==""):return(0,"")]
		[h, if(json.isEmpty(tokenIDs) || indexof(macData,"+")>0): tokenIDs = tokenID]

		[h, if(!isGM() && IamGM): tokenIDs = tokenID]

