[h, if(macDebug): broadcast(" Ba " + damageTotal)]
			[h, macro("Hurt@this"):json.set("","oneToken",if(opt_ATO==2,oneToken,""),"vDamage",damageTotal,"vSilent",1)]
			[h, if(macro.return!=""): macHTML = macHTML + replace(macro.return,"took ",": <b>Damage: ")+"</b> r("+damageDice+")<br>"]
			[h, if(macro.return=="" && opt_ATO!=0): macHTML = macHTML + getName(oneToken)+": <b>Damage: " +if(opt_RML,damageTotal,'<span title="'+damageTotal+' damage">'+macroLink(damageTotal,"Process Macro@this","self",json.append("","hurt",damageTotal,tokenID))+'</span>')+ "</b> r("+damageDice+")<br>"]
[h, if(macDebug): broadcast(" Bb ")]
		}]

		[h, if(hitDice!="" && damageDiceThrown!=""): fullDiceThrown = json.merge("",attackDiceThrown,damageDiceThrown) ; fullDiceThrown = attackDiceThrown]

