[h, if(indexOf(macName,": ")>=0): macName = subString(macName,indexOf(macName,":")+2)]

[h, if(usedSS && opt_ATO && opt_CDD): opt_CDD = 0]


[h, if(IamGM && opt_CDD && indexOf(macDetail,"{@atk")>=0 && !usedSS && opt_ATO!=0): vDrops = strformat('
	<select name=modifier>
		<option>Mod</option><option>1/4</option><option>1/2</option><option>1 &frac14;</option><option>1 &frac12;</option><option>2</option><option>Other</option>
	</select>
	<select name=rollType>
		<option>Roll</option><option>Std</option><option>Adv</option><option>Dis</option>
	</select>') ; vDrops = ""
]

[h, if(IamGM && opt_CSB && opt_COO!=2): shareButton = strformat('<input type="submit" name="submit" value="Share">') ; shareButton = ""]

[h: processorLink = macroLinkText("Perform Macro@Lib:MonsterMaker", "none")]
[h: formAction = strformat('<form action="'+processorLink+'" method="json">')]
[h: outputHeader = strformat('<div style="background-color:'+frameColor+';color:'+color+';border: 1px solid white;padding-top:1px;padding-bottom:0px; padding-left:4px; padding-right:4px; font-size:12pt;">'+formAction)]



[h, if(IamGM && macName!="" && indexOf(macDetail,"{@atk")>=0 && !usedSS && opt_ATO!=0): macButton = '<input type="submit" name="submit" value="'+macName+'" >' ; macButton = ""]

[h, if(libDice==1 && length(fullDiceThrown)>5),CODE:{
	[h, if(isOverlayVisible("DiceOverlay_"+pName+"_Rolled")):closeOverlay("DiceOverlay_"+pName+"_Rolled")]
	[h, if(json.length(fullDiceThrown)>1),CODE:{
		[h, macro("rollDie@this"):json.set("","fullDiceThrown",fullDiceThrown)]
		[h: json.toVars(macro.return)]
		[h: fullDiceThrown = listAppend(fullDiceThrown,"sTokenID="+tokenID+";dTokenID="+json.toList(tokenIDs))]
	}]
}]

[h, if(!json.isEmpty(hitJSON) && indexOf(macDetail,"{@atk")>=0),CODE:{

	[h, if(!opt_RDG),CODE:{
		[h, if(opt_RML): damageOutput = damageTotal;
		 damageOutput = '<span title="'+damageTotal+' damage">'+macroLink(damageTotal,"Process Macro@this","self",json.append("","hurt",damageTotal,tokenID))+' </span>']

		[h, if(damageTotal>0 && !json.isEmpty(damageJSON) || !opt_ATO && json.isEmpty(damageJSON) ): damageOutput = '<font style="font-size:16pt"><b>Damage:'+damageOutput+' </b><font style="font-size:12pt"> r('+damageDice+')<br>' ; damageOutput = ""]
	};{
		[h: damageOutput = ""]
	}]
	[h: json.toVars(hitJSON)]
	[h: hitJSON = json.set(hitJSON,"fullDiceThrown",fullDiceThrown)]
	[h: playerOutput = outputHeader +' <b> '+getName(attackerID)+' attacks: '+macName+'!</b>']
	[h: outputHeader = outputHeader +' <b> '+getName(attackerID)+' attacks: '+if(!usedSS,"</b><br>"+macButton,macName+"</b><br>")]
	[h, if(usedSS || !usedSS && !opt_ATO || !opt_RDG && !opt_ATO): macHTML = '<font style="font-size:16pt"><b>'+if(hitCrit==1,"<i>Critical Hit</i> Attack: ",if(hitCrit==-1,"<i>Failed</i> Attack: ","Attack: "))+if(opt_RML,hitTotal,'<span title="'+hitTotal+' attack">'+macroLink(hitTotal,"Process Macro@this","self",json.append("","ac",encode(hitJSON),attackerID))+'</span>')+'</b><font style="font-size:12pt"> r('+hitAttemptDice+if(hitBonus>0,",+"+hitBonus,if(hitBonus<0,","+hitBonus,""))+')<br>'+damageOutput+macHTML]
};{
	[h: outputHeader = outputHeader +' <b> '+getName(tokenID) + if(macName=="","",": "+macName)+'</b><br>']
	[h: playerOutput = outputHeader]
	[h: outputHeader = outputHeader + customButtons]
}]



[h: outputFooter = '<input type="hidden" name="usedSS" value="'+usedSS+'"></form><div style="background-color:#FFFFFF;color:'+color+'; padding:2px;"><div style=" color: #000000; padding:2px; margin-bottom:-5px; font-size:12pt;text-align:left">'+macHTML+'</div></div>']

[h: playerOutput = encode( playerOutput+outputFooter)]

[h: outputButtons = strformat('<input type="hidden" name="tokenID" value="'+tokenID+'"><input type="hidden" name="pOutput" value="'+playerOutput+'"><input type="hidden" name="macDetail" value="'+macDetail+'"><input type="hidden" name="hitJSON" value="'+encode(hitJSON)+'">')]

[h: finalOutput = outputHeader+outputButtons+vDrops+shareButton+outputFooter]

[h, if(macDebug):broadcast("Used SS "+usedSS)]

[h, if(libDice==1 && usedSS),CODE:{
	[h, if(json.length(tokenIDs)==1): tokenIDs = json.get(tokenIDs,0) ; tokenIDs = json.toList(tokenIDs)]
	[h, if(json.length(dTokenID)==1): dTokenID = json.get(dTokenID,0) ; dTokenID = json.toList(dTokenID)]
	[h: fullDiceThrown = json.toList(fullDiceThrown)]
	[h, if(findToken(sTokenID)!=""): fullDiceThrown = fullDiceThrown+";sTokenID="+sTokenID]
	[h, if(findToken(dTokenID)==""): dTokenID = tokenIDs]
	[h, if(findToken(dTokenID)!=""): fullDiceThrown = fullDiceThrown+";dTokenID="+dTokenID ; fullDiceThrown = fullDiceThrown+if(findToken(attackerID)!="",";dTokenID="+attackerID,"")]
[h, if(macDebug): broadcast("full end   " +fullDiceThrown)]

	[h: tokDiceProp = json.set(tokDiceProp,"runAfter",json.set("","macro","Process Macro@Lib:MonsterMaker","params",encode(finalOutput),"player",pName))]
	[h: setLibProperty("LibDiceOverlay",tokDiceProp,"lib:"+pName)]
	[h: rollDO(fullDiceThrown)]
	[h: return(0,"")]
};{
	[h, macro("scrubLinks@this"):json.append("full",encode(finalOutput))]
	[h: pOutput = decode(macro.return)]	
	[h, if(opt_COO!=2 && !isGM()),CODE:{
		[h, macro("scrubLinks@this"):json.append("noShare",encode(finalOutput))]
		[h: sOutput = decode(macro.return)]
		[h: broadcast(sOutput,pName)]	
		[h: execFunction("broadcast",json.append("",finalOutput,"self"),1,gmList)]
	};{
		[h, if(isGM()): broadcast(finalOutput,gmList) ; broadcast(pOutput,chatList)]
	}]
}]

[h: tokenRef = getMacroLocation()]
[h, if(startsWith(tokenRef,"Token:")),CODE:{
	[h: tokenRef = findToken(getSelected())]
	[h, if(listCount(tokenRef)>1 || tokenRef==""):return(0)]
}]
[h: tMacro=getMacroButtonIndex()]
[h: tGroup=json.get(getMacroProps(tMacro,"json",tokenRef),"group")]
[h: tMacroIDs=getMacroGroup(tGroup,",",tokenRef)]
[h: vThisMacro = getMacroName()]
[h: vExpandedLabel  = "Collapse "+tGroup]
[h: vCollapsedLabel = "Expand "+tGroup]
[h: vMacID = getMacroButtonIndex()]
[h: vThisMacroProps = getMacroProps(getMacroButtonIndex(),",",tokenRef)]
[h, if(matches(vThisMacro, vExpandedLabel) || matches(vThisMacro, "Collapse")), code: {
	[h: setMacroProps(getMacroButtonIndex(), json.set("{}", "label", vCollapsedLabel), "json",tokenRef)]
	[h: expand = 1]
};{
	[h: setMacroProps(getMacroButtonIndex(), json.set("{}", "label", vExpandedLabel), "json",tokenRef)]
	[h: expand = 0]
}]
[h, foreach(tMacro,tMacroIDs), CODE:{
	[h: macJSON = getMacroProps(tMacro,"json",tokenRef)]
	[h: maxWidth = ""]
	[h: json.toVars(macJSON)]
	[h, if(sortBy == ""):sortBy = 1]
	[h, if(expand),CODE:{
		[h: "grow stuff"]
		[h: json.toVars(maxWidth)]
		[h: macJSON = ""]
		[h: setMacroProps(tMacro, json.set("{}", "maxWidth", macJSON,"fontSize", fsize,"minWidth", width,"sortBy",sortBy), "json",tokenRef)]
	};{
		[h: "shrink stuff"]
		[h: macJSON = json.set("","width",minWidth,"fsize",fontSize)]
		[h: setMacroProps(tMacro, json.set("{}", "maxWidth", macJSON), "json",tokenRef)]
		[h: minWidth = "0"]
		[h: fontSize = "0.0em"]
		[h, if(tMacro != vMacID): setMacroProps(tMacro, json.set("{}", "fontSize", fontSize,"minWidth", minWidth,"sortBy",sortBy), "json",tokenRef)]
	}]
}]

