[r: vMsg]

[h: "If 1 show all spells, otherwise show only learnt spells"]
[h: vCast = 0]
[h, if(macro.args == 'cast'): vCast = 1]

[h: "Get correct JS script from the displaySpell macro"]
[h: vLib   = 'Lib:SpellLibrary']
[h: vMap   = getTokenMap(vLib)]
[h: vIndex = getMacroIndexes('displaySpell', ',', vLib, vMap)]
[h: vMacro = getMacroCommand( listGet(vIndex, 0), vLib, vMap)]


[h: "Get correct JS script from the displayLibrary macro"]
[h: vIndexLibrary = getMacroIndexes('displayLibrary', ',', vLib, vMap)]
[h: vMacroLibrary = getMacroCommand( listGet(vIndexLibrary, 0), vLib, vMap)]

[h: "Get the token used to learn or cast the spells"]
[macro("getCasterToken@Lib:SpellLibrary"):""]
[h: vCurrentId = macro.return]


[h: "If valid token, take known spell list"]
[h, if(vCurrentId != ""), CODE:{
	[switchToken(vCurrentId)]
	[vKnown = getProperty("Spells")]
	[vName  = getName()]
	[vOrder = getProperty("SpellbookOrder")]
	[if(json.isEmpty(vKnown)): vKnown = "{}"]
	[if(json.isEmpty(vOrder)): vOrder = "[]"]
};{
	[vCast  = 0]
	[vKnown = "{}"]
	[vName = ""]
	[vOrder = "[]"]
}]

[h: vCustomSpells = getLibProperty('CustomSpells', vLib)]
[h: vHasCustom    = if( json.isEmpty(vCustomSpells), 0, 1)]

[macro("getDefaultAbility@Lib:SpellLibrary"):vCurrentId]
[h: vDefaultStat = macro.return]
[h: vDefaultDC = 15]

[h: vTitle = if(vCast, "Spellbook", "Spell Library") + if(vName != "", " - " + vName, "")] 

[frame5(vTitle,"temporary=0"):{
<head><link rel="stylesheet"  href="lib://SpellLibrary/macro/CSS?cachelib=false"></link></head>

[macro("formElements@" + vLib):json.set("{}", "Name", vName, "CurrentId", vCurrentId, "ShowList", 1, "Cast", vCast, "HasCustom", vHasCustom)]

[r: vMacro]
[r: vMacroLibrary]

<script> 
	var vSpells       = [r: getLibProperty('Spells', vLib)];
	var vCustomSpells = [r: vCustomSpells];
	var vKnown  = [r: vKnown];
	var vCasterId = '[r: vCurrentId]';
	var vCasterName = '[r: vName]';
	var vIsToken = vCasterId !== '';
	var vDefaultStat = '[r: vDefaultStat]';
	var vDefaultDC   = '[r: vDefaultDC]';

	var vCast = ([r: vCast] == 1) && vIsToken;
	var vIsGM = ([r:isGM()] == 1);

	var vListedSpells = vCast == 1 ? vSpells.concat(vCustomSpells).filter(filterKnownSpells) : vSpells.concat(vCustomSpells);

	var vLength = vListedSpells.length;

	var vOrder  = [r: vOrder];

	var linkCondition = "[r: macroLinkText('condition@Lib:SpellLibrary', 'all', '', vCurrentId)]";
	var linkDamage = "[r: macroLinkText('damage@Lib:SpellLibrary', 'all', '', vCurrentId)]";
	var linkHit = "[r: macroLinkText('hit@Lib:SpellLibrary', 'all', '', vCurrentId)]";
	var linkCreature = "[r: macroLinkText('creature@Lib:SpellLibrary', 'all', '', vCurrentId)]";
	var linkRoll = "[r: macroLinkText('roll@Lib:SpellLibrary', 'all', '', vCurrentId)]";
	var linkChance = "[r: macroLinkText('chance@Lib:SpellLibrary', 'all', '', vCurrentId)]";
	var linkAttack = "[r: macroLinkText('attack@Lib:SpellLibrary', 'all', '', vCurrentId)]";
	var linkSavingThrow = "[r: macroLinkText('savingThrow@Lib:SpellLibrary', 'all', '', vCurrentId)]";
	var linkCheck = "[r: macroLinkText('check@Lib:SpellLibrary', 'all', '', vCurrentId)]";
	var linkSkill = "[r: macroLinkText('skill@Lib:SpellLibrary', 'all', '', vCurrentId)]";
	var linkSpell = "[r: macroLinkText('Show a Spell@Lib:SpellLibrary', 'none', '', vCurrentId)]";
	var linkConcentration = "[r: macroLinkText('concentration@Lib:SpellLibrary', 'all', '', vCurrentId)]";
	var linkShare = "[r: macroLinkText('share@Lib:SpellLibrary', 'all', '', vCurrentId)]";
	var linkMacro = "[r: macroLinkText('createMacro@Lib:SpellLibrary', 'self', '', vCurrentId)]";

	const QuoteSymbol = unescape("%27");
</script>

<body onload='CreateTable();'></body>


