table {width: 90%;}

.searchBar {
	background-position: 10px 12px;
	background-repeat: no-repeat;
	width: 90%;
	font-size: 16px;
	padding: 12px 20px 12px 40px;
	border: 1px solid #ddd;
	margin-bottom: 12px;
}

.circle {
	height:4px;
	width: 4px;
	border-radius: 50%;
	border: 2px solid #4a6898;
	cursor: grab;
}

table.editCustomSpell{
	border-spacing: 0;
	border-collapse: collapse;
}

.dropdown {
  position: relative;
  display: inline-block;
}

.dropbtn {
  color: #822000;
  padding: 2px;
  font-size: 1em;
  border: none;
  cursor: grab;
  background-color: #FDF1DC;
  font-family: Georgia, serif;
}

.dropbtn:hover, .dropbtn:focus {
  background-color: #FAEBD7;
}


/* Dropdown Content (Hidden by Default) */
.dropdown-content {
  display: none;
  position: absolute;
  background-color: #f1f1f1;
  min-width: 160px;
  box-shadow: 0px 8px 16px 0px rgba(0,0,0,0.2);
  z-index: 1;
}

/* Show the dropdown menu (use JS to add this class to the .dropdown-content container when the user clicks on the dropdown button) */
.show {display:block;}


/* Choices inside the dropdown */
.dropdown-content span {
  color: black;
  padding: 12px 16px;
  text-decoration: none;
  display: block;
}


.circle.prepared {
	background-color: #4a6898;
}

.circle.always{
	background-color: green;
	border: 2px solid green;
	cursor: default;
}


.learn {
    background-color:#4a6898;
    color: #fff;
    font-size: 0.8em;
}

.forget {
    background-color:#822000;
    color: #fff;
    font-size: 0.7em;
    padding-top: 4px;
    padding-bottom: 3px;
}


.spellName {
	float: left;
	color: #822000;
	font-size: 1.4em;
}

.source {
	position: absolute;
	right: 10px;
	color: #4a6898;
	font-size: 1.4em;
}

body {
    background-color: #FDF1DC;
	font-family: Georgia, serif;
	line-height: 2.5;
}


.schoolLevel {
	font-style: italic;
}

.share {
	text-align: right;
}

.macro {
	text-align: right;
	font-size: 0.7em;
}

.page {
	font-size: 0.6em;
	color: #333333;
}

.label {font-weight: bold;	}

p { line-height: 1.5; }

td {line-height: 1.5;}

.toggle {
	font-size: 1.2em;
	font-weight: bold;
	cursor: grab;
	text-align: center;
	vertical-align: center;
}

.divider {
	border-top: 2px solid black;
}

.middivider {
	border-top: 0px solid black;
}

.caption {
	color: #777777;
	font-size: 1.1em;
	font-weight: bold;
}

.header {
	color: #822000;
	font-weight: bold;
}

.smalltable{
	width: 0px;
	margin: 0 auto;
}

a{
	color: #822000;
}


.pseudolink {
  background: none!important;
  border: none;
  padding: 0!important;
  color: #822000;
  text-decoration: underline;
  cursor: pointer;
  font-family: Georgia, serif;
  font-size: 1em;
}


.spellHeader{
	 -webkit-user-select: none;	
}

.unselectable {
	 -webkit-user-select: none;
}

/* Style the buttons */
.selector {
  border: none;
  outline: none;
  padding: 8px 12px;
  background-color: #f1f1f1;
  cursor: pointer;
  width: 70px;
}

.selector:hover {
  background-color: #ddd;
}

.selector.active {
  background-color: #666;
  color: white;
}

[h: vSpell  = json.get(macro.args, "spell")]
[h: vAction = json.get(macro.args, "action")]
[h: vStat = json.get(macro.args, "stat")]
[h: vSpells = getProperty("Spells")]
[h: vMacroName = 'Spellbook']

[if(vAction == 'forget'), CODE:{
	[h: vSpells = json.remove(vSpells, vSpell)]
	Forgot [r:vSpell].
};{}]

[if(vAction == 'learn'), CODE:{
	[h: jsonSpell = json.set("{}", "stat", json.get(macro.args, "stat"), "prepared", "no")]
	[h: vSpells = json.set(vSpells, vSpell, jsonSpell)]
	Learned [r:vSpell].

	[h: vAddBookMacro = 0]
	[h, if(!hasMacro(vMacroName)), CODE:{
		[vOption = getLibProperty("BookMacroOption")]
		[if (vOption == "" || vOption == "On Learning First Spell"): vAddBookMacro = if(json.length(vSpells) == 1, 1, 0)]
		[if (vOption == "On Learning Any Spell"): vAddBookMacro = 1]
	};{}]

	[h, if (vAddBookMacro), CODE:{
		[vCommand = '[macro("Spell Library@Lib:SpellLibrary"):"cast"]']
		[vTooltip=  'Consults the spell book of the character. To add a spell to the spellbook, click on the Spell Library macro.']
		[vProp    = json.set("{}", "color", "blue", "fontColor", "white", "playerEditable", 0, "tooltip", vTooltip, "group", "Spells")]
		[createMacro(vMacroName, vCommand, vProp, 'json')]
	};{}]
};{}]


[if(vAction == 'prepare'), CODE:{
	[h: jsonSpell = json.get(vSpells, vSpell)]
	[h: jsonSpell = json.set( jsonSpell, 'prepared', 'yes')]
	[h: vSpells = json.set(vSpells, vSpell, jsonSpell)]
	Prepared [r:vSpell].
};{}]

[if(vAction == 'unprepare'), CODE:{
	[h: jsonSpell = json.get(vSpells, vSpell)]
	[h: jsonSpell = json.set( jsonSpell, 'prepared', 'no')]
	[h: vSpells = json.set(vSpells, vSpell, jsonSpell)]
	Unprepared [r:vSpell].
};{}]

[if(vAction == 'changeStat'), CODE:{
	[h: jsonSpell = json.get(vSpells, vSpell)]
	[if (json.isEmpty(jsonSpell) == 0), CODE:{
		[h: jsonSpell = json.set( jsonSpell, 'stat', vStat)]
		[h: vSpells = json.set(vSpells, vSpell, jsonSpell)]
		Changed [r:vSpell] Spellcasting Ability to [r:vStat].
	};{}]
};{}]


[h: setProperty("Spells", vSpells)]

[h, if(macro.args == ""), CODE:{

	[macro.return = "Charisma"]

}; {
	[switchToken(macro.args)]
	[vInt = getProperty("IntMod")][h: vWis = getProperty("WisMod")][h: vCha = getProperty("ChaMod")]

	[if(isNumber(vInt) == 0) : vInt = -5][h, if(isNumber(vWis) == 0) : vWis = -5][h, if(isNumber(vCha) == 0) : vCha = -5]

	                          [vMaxStat = 'Charisma']     [vMax = vCha]
	[if (vInt > vMax), CODE:{ [vMaxStat = 'Intelligence'] [vMax = vInt] }]
	[if (vWis > vMax), CODE:{ [vMaxStat = 'Wisdom'      ] [vMax = vWis] }]

	[macro.return = vMaxStat]
}]

[h: vSpell = macro.args]

[h, if(indexOf(vSpell," Spell")>=1),CODE:{
	[h: oldSpell = substring(vSpell,0,indexOf(vSpell," Spell")+6)]
	[h: closeFrame(oldSpell)]
	[h: vSpell  = substring(vSpell,indexOf(vSpell," Spell")+6)]
}]

[h, if(vSpell == ""): vSpell = 'Fireball']

[h: vLib   = 'Lib:SpellLibrary']
[h: vMap   = getTokenMap(vLib)]
[h: vIndex = getMacroIndexes('displaySpell', ',', vLib, vMap)]
[h: vMacro = getMacroCommand( listGet(vIndex, 0), vLib, vMap)]

[macro("getDefaultAbility@Lib:SpellLibrary"):""]
[h: vDefaultStat = macro.return]
[h: vDefaultDC = 15]

[macro("getCasterToken@Lib:SpellLibrary"):""]
[h: vCurrentId = macro.return]

[h: "If valid token, take known spell list"]
[h, if(vCurrentId != ""), CODE:{
	[switchToken(vCurrentId)]
	[vKnown = getProperty("Spells")]
	[vName  = getName()]
	[if(json.isEmpty(vKnown)): vKnown = "{}"]
	[macro("getDefaultAbility@Lib:SpellLibrary"):vCurrentId]
	[vDefaultStat = macro.return]
};{
	[vKnown = "{}"]
	[vName = ""]
}]

[h: vTitle = capitalize(vSpell) + " Spell" + if(vName != "", " - " + vName, "")] 

[frame5(vTitle, "width=550; height=450; temporary=1"):{
<head><link rel="stylesheet"  href="lib://SpellLibrary/macro/CSS?cachelib=false"></link></head>

[macro("formElements@" + vLib):json.set("{}", "Name", vName, "CurrentId", vCurrentId, "ShowList", 0, "Cast", if(vCurrentId == "", 0, 1))]

[r: vMacro]

<script> 
	var vSpells  = [r: getLibProperty('Spells', vLib)];
	var vCustomSpells = [r: getLibProperty('CustomSpells', vLib)];
	var vSpell = vSpells.find(el => el.name.toLowerCase() === "[r: vSpell]".toLowerCase());
	vSpell = vSpell || vCustomSpells.find(el => el.name.toLowerCase() === "[r: vSpell]".toLowerCase());

	var vIsGM = ([r:isGM()] == 1);

	var vKnown  = [r: vKnown];
	var vCasterId = '[r: vCurrentId]';
	var vCasterName = '[r: vName]';
	var vIsToken = vCasterId !== '';
	var vDefaultStat = '[r: vDefaultStat]';
	var vDefaultDC   = '[r: vDefaultDC]';

	var linkCondition = "[r: macroLinkText('condition@Lib:SpellLibrary', 'all', '', vCurrentId)]";
	var linkDamage = "[r: macroLinkText('damage@Lib:SpellLibrary', 'all', '', vCurrentId)]";	
	var linkHit = "[r: macroLinkText('hit@Lib:SpellLibrary', 'all', '', vCurrentId)]";
	var linkCreature = "[r: macroLinkText('creature@Lib:SpellLibrary', 'all', '', vCurrentId)]";
	var linkRoll = "[r: macroLinkText('roll@Lib:SpellLibrary', 'all', '', vCurrentId)]";
	var linkChance = "[r: macroLinkText('chance@Lib:SpellLibrary', 'all', '', vCurrentId)]";
	var linkAttack = "[r: macroLinkText('attack@Lib:SpellLibrary', 'all', '', vCurrentId)]";
	var linkSavingThrow = "[r: macroLinkText('savingThrow@Lib:SpellLibrary', 'all', '', vCurrentId)]";
	var linkCheck = "[r: macroLinkText('check@Lib:SpellLibrary', 'all', '', vCurrentId)]";
	var linkSkill = "[r: macroLinkText('skill@Lib:SpellLibrary', 'all', '', vCurrentId)]";
	var linkSpell = "[r: macroLinkText('Show a Spell@Lib:SpellLibrary', 'none', vTitle, vCurrentId)]";
	var linkConcentration = "[r: macroLinkText('concentration@Lib:SpellLibrary', 'all', '', vCurrentId)]";
	var linkShare = "[r: macroLinkText('share@Lib:SpellLibrary', 'all', '', vCurrentId)]";
	var linkMacro = "[r: macroLinkText('createMacro@Lib:SpellLibrary', 'self', '', vCurrentId)]";

	const QuoteSymbol = unescape("%27");
</script>

<script>
[r: "function ShowSpell(){
		try{
			let table = document.createElement('table');

			let tr = table.insertRow(-1);
			let td = tr.insertCell(-1);
			td.appendChild(GetSpellDesc(vSpell));

			document.body.appendChild(table);
		} catch (err){
			console.log(err);
		}
}"]
</script>

<body onload='ShowSpell();'></body>

}]

[h: "SPELL PROPERTIES "]
[h: vSpellName   = json.get(macro.args, 'spell')]
[h: vSpellLink   = macroLink(vSpellName, "Show a Spell@Lib:SpellLibrary", "none", vSpellName, "impersonated")]

[if(state.Concentrating == 1 && getProperty("Concentration") == vSpellName), CODE:
{
     [h:state.Concentrating=0][h:Concentration=""]
     [r: getName()] stopped concentrating on [r:vSpellLink].
};{
     [h:state.Concentrating=1]
     [h: setProperty("Concentration", vSpellName)]
     [r: getName()] is concentrating on [r:vSpellLink].
}]

[h: vName   = replace(json.get(macro.args, "name"), "'", "`")]
[h: vSpell  = json.set("{}", "name", vName)]

[h: vSource = json.get(macro.args, "source")]
[h: vPage   = json.get(macro.args, "page")]
[h: vLevel  = json.get(macro.args, "level")]
[h: vSchool = json.get(macro.args, "school")]
[h: vTimeType = json.get(macro.args, "timeType")]
[h: vTimeAmount = json.get(macro.args, "timeAmount")][h, if(isNumber(vTimeAmount) == 0): vTimeAmount = 1]
[h: vCondition  = trim(json.get(macro.args, "condition"))]
[h: vClasses = json.get(macro.args, "classes")]
[h: vRaces   = trim(json.get(macro.args, "races"))]
[h: vSubclasses   = trim(json.get(macro.args, "subclasses"))]
[h: vDescription  = trim(json.get(macro.args, "description"))]

[h: vRangeAmount = json.get(macro.args, "rangeAmount")][h, if(isNumber(vRangeAmount) == 0): vRangeAmount = 5]
[h: vRangeType   = json.get(macro.args, "rangeType")]
[h: vShape       = json.get(macro.args, "shape")]

[h: vVerbal = if(json.get(macro.args, "verbal") == "", 0, 1)]
[h: vSomatic = if(json.get(macro.args, "somatic") == "", 0, 1)]
[h: vMaterial = trim(json.get(macro.args, "material"))]

[h: vRitual = if(json.get(macro.args, "ritual") == "", 0, 1)]
[h: vConcentration = if(json.get(macro.args, "concentration") == "", 0, 1)]

[h: vDurationAmount = json.get(macro.args, "durationAmount")][h, if(isNumber(vDurationAmount) == 0): vDurationAmount = 1]
[h: vDurationType   = json.get(macro.args, "durationType")]

[h: vSavingThrow    = json.get(macro.args, "savingThrow")]

[h: vOldName        = json.get(macro.args, "oldName")]

[h,switch(vTimeType),code:
case "Action":       {[vTime = json.set("{}", "number", vTimeAmount, "unit", "action"  , "inMinutes", vTimeAmount/10)]};
case "Bonus": {[vTime = json.set("{}", "number", vTimeAmount, "unit", "bonus"   , "inMinutes", vTimeAmount/20)]};
case "Reaction":     {[vTime = json.set("{}", "number", vTimeAmount, "unit", "reaction", "inMinutes", vTimeAmount/50)]};
case "Rounds":       {[vTime = json.set("{}", "number", vTimeAmount, "unit", "round"   , "inMinutes", vTimeAmount/10)]};
case "Minutes":      {[vTime = json.set("{}", "number", vTimeAmount, "unit", "minute"  , "inMinutes", vTimeAmount   )]};
case "Hours":        {[vTime = json.set("{}", "number", vTimeAmount, "unit", "hour"    , "inMinutes", vTimeAmount*60)]};
default: {}
]
[h, if (vCondition != ""): vTime = json.set(vTime, "condition", vCondition)][h: vTime = json.append("[]", vTime)]

[h,switch(vRangeType),code:
case "special":      {[vRange = json.set("{}", "type", "special", "inFeet", 3000002)]};
case "unlimited":    {[vRange = json.set("{}", "type",    vShape, "inFeet", 3000003, "distance", json.set("{}", "type", "unlimited"))]};
case "sight":        {[vRange = json.set("{}", "type",    vShape, "inFeet", 3000001, "distance", json.set("{}", "type", "sight"))]};
case "self":         {[vRange = json.set("{}", "type",    vShape, "inFeet",       0, "distance", json.set("{}", "type", "self"))]};
case "touch":        {[vRange = json.set("{}", "type",    vShape, "inFeet",     2.5, "distance", json.set("{}", "type", "touch"))]};
case "feet" :        {[vRange = json.set("{}", "type",    vShape, "inFeet",vRangeAmount, "distance", json.set("{}", "type", "feet", "amount", vRangeAmount))]};
case "miles":        {[vRange = json.set("{}", "type",    vShape, "inFeet",vRangeAmount*5280, "distance", json.set("{}", "type", "mile", "amount", vRangeAmount))]};
default: {}
]

[h,switch(vDurationType),code:
case "permanent":    {[vDuration = json.set("{}", "type", "permanent", "inMinutes", 99999)]};
case "special":      {[vDuration = json.set("{}", "type", "special"  , "inMinutes", 99998)]};
case "instant":      {[vDuration = json.set("{}", "type", "instant"  , "inMinutes",     0)]};
case "rounds":       {[vDuration = json.set("{}", "type", "timed"    , "inMinutes", vDurationAmount/10   , "duration", json.set("{}", "type", "round", "amount", vDurationAmount))]};
case "minutes":      {[vDuration = json.set("{}", "type", "timed"    , "inMinutes", vDurationAmount      , "duration", json.set("{}", "type", "minute", "amount", vDurationAmount))]};
case "hours":        {[vDuration = json.set("{}", "type", "timed"    , "inMinutes", vDurationAmount*60   , "duration", json.set("{}", "type", "hour", "amount", vDurationAmount))]};
case "days":         {[vDuration = json.set("{}", "type", "timed"    , "inMinutes", vDurationAmount*60*24, "duration", json.set("{}", "type", "day", "amount", vDurationAmount))]};
default: {}
]

[h, if (vConcentration): vDuration = json.set(vDuration, "concentration", "true")][h: vDuration = json.append("[]", vDuration)]


[h: vComponents = "{}"]
[h, if(vVerbal): vComponents =json.set(vComponents, "v", "true")]
[h, if(vSomatic): vComponents =json.set(vComponents,"s", "true")]
[h, if(vMaterial != ""): vComponents =json.set(vComponents, "m", json.set("{}", "text", vMaterial))]

[h: vMeta = "{}"]
[h, if (vRitual): vMeta = json.set(vMeta, "ritual", "true")]

[h: vAllClasses    = "{}"]
[h: vFromClassList = "[]"]
[h: vFromSubclass  = "[]"]
[h: vFromRaces     = "[]"]

[h, foreach(vClass, vClasses): vFromClassList = json.append(vFromClassList, json.set("{}", "name", vClass))]
[h, if(json.isEmpty(vFromClassList) != 1): vAllClasses = json.set(vAllClasses, "fromClassList", vFromClassList)]

[h, foreach(vClass, vSubclasses): vFromSubclass = json.append(vFromSubclass, json.set("{}", "subclass", json.set("{}", "name", vClass)))]
[h, if(json.isEmpty(vFromSubclass) != 1): vAllClasses = json.set(vAllClasses, "fromSubclass", vFromSubclass)]

[h, if(json.isEmpty(vAllClasses) != 1): vSpell = json.set(vSpell, "classes", vAllClasses)]

[h, foreach(vRace, vRaces): vFromRaces = json.append(vFromRaces, json.set("{}", "name", vRace))]
[h, if(json.isEmpty(vFromRaces) != 1): vSpell = json.set(vSpell, "races", vFromRaces)]

[h, if(vSavingThrow != ""): vSpell = json.set(vSpell, "savingThrow", json.append("[]", vSavingThrow))]

[h: vEntries = json.append("[]", vDescription)]

[h: "ADD THE NEW SPELL"]

[h: vSpell = json.set(vSpell, "source", vSource, "page", vPage, "level", vLevel, "school", vSchool, "time", vTime, "range", vRange, "components", vComponents, "duration", vDuration, "meta", vMeta, "entries", vEntries, "custom", "true")]

[h: vCustomSpells = getLibProperty("CustomSpells")]

[h: vCustomSpells = json.path.delete(vCustomSpells, ".[?(@.name == '"+ vOldName +"')]")]
[h: vCustomSpells = json.path.delete(vCustomSpells, ".[?(@.name == '"+  vName   +"')]")]
[h: vCustomSpells = json.append(vCustomSpells, vSpell)]

[h: setLibProperty("CustomSpells", vCustomSpells)]
[h: vIndex = json.length(vCustomSpells)-1]

[macro("Add Custom Spell@this"):vIndex]

[h: vLink = macroLink(vName, "Show a Spell@Lib:SpellLibrary", "none", vName)]
[r: if(vOldName == "", "Spell Added: ", "Spell Modified: ") + vLink]

[H: vCustomSpells = getLibProperty("CustomSpells")]

[H, if(json.isEmpty(vCustomSpells)): assert(0, "No spells to modify")]


[H: vChoices = "[]"]
[H, foreach(vSpell,vCustomSpells), CODE: {
	[H: vChoice = json.get(vSpell, "name")]
	[H: vChoices = json.append(vChoices, vChoice)]
}]

[H: flag = input("vIndex|" + vChoices + "|Select Spell to Edit|LIST|DELIMITER=JSON",
"dummy|dummy|        OR|LABEL|TEXT=FALSE",
"vDelete|0|Delete this spell ?|CHECK")]

[H: abort(flag)]

[r, if(vDelete == 1), CODE:{
	[h: vCustomSpells = json.remove(vCustomSpells, vIndex)]
	[h: setLibProperty("CustomSpells", vCustomSpells)]
};{
	[macro("Add Custom Spell@this"):vIndex]
}]

[h: vSpellName = json.get(macro.args, "spell")]
[h: vLevel     = json.get(macro.args, "level")]
[h: vSchool    = json.get(macro.args, "school")]


[h,switch(vSchool),code:
	case "A": { [vFontColor = "white"] [vColor = "blue"]};
	case "C": { [vFontColor = "black"] [vColor = "orange"]};
	case "D": { [vFontColor = "black"] [vColor = "white"]};
	case "E": { [vFontColor = "black"] [vColor = "yellow"]};
	case "V": { [vFontColor = "white"] [vColor = "red"]};
	case "I": { [vFontColor = "white"] [vColor = "purple"]};
	case "N": { [vFontColor = "white"] [vColor = "black"]};
	case "T": { [vFontColor = "white"] [vColor = "green"]};
	default : { [vFontColor = "black"] [vColor = "default"]}]

[r, if(!hasMacro(vSpellName)), CODE:{
		[h: vCommand = "[macro('Show a Spell@Lib:SpellLibrary'):'" + vSpellName + "']"]
		[h: vTooltip=  'Show the ' + vSpellName + ' spell.']
		[h: vProp    = json.set("{}", "color", vColor, "fontColor", vFontColor, "playerEditable", 0, "tooltip", vTooltip, "group", "Spells", "sortBy", "_"+vLevel)]
		[h: createMacro(vSpellName, vCommand, vProp, 'json')]
		Added [r:vSpellName] macro.
};{
	    [r:vSpellName] macro already exists.
}]

[h: tParse = macro.args]

[h, if(length(tParse)<=0),CODE:{
[h: text='<html><br>Syntax for use - macro("Spell Lookup@Lib:SpellLibrary"):Td<br>'+
'&nbsp;&nbsp;Where T is for type: S or L<br>'+
'&nbsp;&nbsp;Where d is for data:<br>'+
'&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;if S, data is a spellname<br>'+
'&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;if L data is a level and class syntax: Lc<br>'+
'&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;L is for level 0-9<br>'+
'&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;c is for class acronym (wiz, dru, etc)</html>']
	[assert(0, text)]
}]

[h: tLookupType = substring(tParse,0,1)]

[h, if(tLookupType=="L"),CODE:{	
	[h: tLevel = substring(tParse,1,2)]
	[h: tClass = substring(tParse,2)]
	[h: tData = ""]
};{
	[h: tLevel = ""]
	[h: tClass = ""]
	[h: tData = substring(tParse,1)]
}]

[h: allSpells = getLibProperty("Spells","Lib:SpellLibrary")]
[h: allCustomSpells = getLibProperty("CustomSpells","Lib:SpellLibrary")]

[h: allSpells = json.merge(allSpells,allCustomSpells)]

[h: sLoop = 0][h: Done = 0]
[h, while(sLoop<=1000 && Done==0 && length(allSpells)>=10),CODE:{
	[h: oneSpell = json.get(allSpells,0)]
	[h: sName = json.get(oneSpell,"name")]
	[h: sLevel = json.get(oneSpell,"level")]
	[h: sClass = json.path.read(oneSpell,".classes..name")]
	[h, if(tLookupType=="S" && lower(sName)==tData),CODE:{
		[h: sLevel = if(sLevel=="0","c",sLevel)]
		[h: tData = sName+","+sLevel]
		[h: Done = 1]
	}]
	[h, if(tLookupType=="L" && tLevel==sLevel && indexOf(sClass,tClass)>=0),CODE:{
		[h: tData = listAppend(tData,sName)]
	}]
	[h: allSpells = json.remove(allSpells,0)]
	[h: sLoop = sLoop + 1]
}]
[h, if(tLookupType=="S" && Done==0),CODE:{
	[h, if(indexOf(tData,"'")>=0),CODE:{
		[h: tData = "S"+replace(tData,"'","`")]
		[macro("Spell Lookup@Lib:SpellLibrary"):tData]
	};{
		[h: setProperty("Testing",tData,findToken("TrnTkn"))]
		[abort(SPELL_LOOKUP_SPELLLIBRARY_NOT_FOUND)]
	}]
}]
[h: macro.return=tData]
[h: 'abort(DEBUG_Spell_Lookup_Lib_SpellLibrary)']

[h, if(getInitiativeToken() == currentToken()), code: 
{ 
	[message = add(token.name, " ends ", PronounPossessive, " turn.")] 
	[broadcast(message)] 
	[nextInitiative()]
}; 
{
	[message = add("<i style='color:gray;'>It is not ", token.name, "'s turn!</i>")]
	[broadcast(message, getPlayerName(), "gm")]
};]

